def test_click_positions_pointer_absolutely_then_presses(xtest_recorder) -> None:
    events, display = xtest_recorder
    _linux_input.click(500, 400)
    assert events == [(_X_MOTION, 0, 500, 400), (_X_BPRESS, 1, 0, 0), (_X_BRELEASE, 1, 0, 0)]
    assert display.warps == [], "relative warp_pointer must never be used for coordinates"
    assert display.syncs == 1  # one flush per logical operation


def test_click_button_and_count(xtest_recorder) -> None:
    events, _ = xtest_recorder
    _linux_input.click(10, 20, button="right", count=2)
    assert events[0] == (_X_MOTION, 0, 10, 20)
    assert events[1:] == [(_X_BPRESS, 3, 0, 0), (_X_BRELEASE, 3, 0, 0)] * 2


@pytest.mark.parametrize("count", [1, 2, 3])
@pytest.mark.parametrize("button, number", [("left", 1), ("right", 3), ("middle", 2)])
def test_click_delivers_pairs_with_an_inter_click_gap(
    xtest_recorder, monkeypatch, count, button, number,
) -> None:
    """Timestamp delivered events, so sleeping before a final-only sync fails."""
    import time

    events, display = xtest_recorder
    now = 0.0
    delivered = []
    sleeps = []
    sent = 0

    def sync():
        nonlocal sent
        delivered.extend((event, now) for event in events[sent:])
        sent = len(events)

    def sleep(seconds):
        nonlocal now
        sleeps.append(seconds)
        now += seconds

    monkeypatch.setattr(display, "sync", sync)
    monkeypatch.setattr(time, "sleep", sleep)
    _linux_input.click(406, 465, button=button, count=count)

    assert delivered[0] == ((_X_MOTION, 0, 406, 465), 0.0)
    assert [event for event, _ in delivered[1:]] == [
        (_X_BPRESS, number, 0, 0), (_X_BRELEASE, number, 0, 0),
    ] * count
    assert [timestamp for _, timestamp in delivered[1:]] == pytest.approx([
        index * 0.03 for index in range(count) for _ in range(2)
    ])
    assert sleeps == [0.03] * (count - 1)
    assert now == pytest.approx((count - 1) * 0.03)


def test_drag_moves_absolutely_at_both_endpoints(xtest_recorder, monkeypatch) -> None:
    monkeypatch.setattr(_linux_input, "DRAG_PACE_S", 0)
    monkeypatch.setattr(_linux_input, "DRAG_THRESHOLD_PAUSE_S", 0)
    monkeypatch.setattr(_linux_input, "DRAG_HOVER_S", 0)
    events, display = xtest_recorder
    _linux_input.drag(10, 20, 300, 400)
    assert events[:2] == [(_X_MOTION, 0, 10, 20), (_X_BPRESS, 1, 0, 0)]
    assert events[-2:] == [(_X_MOTION, 0, 300, 400), (_X_BRELEASE, 1, 0, 0)]
    motions = [(x, y) for kind, _d, x, y in events[2:-1]]
    assert all(kind == _X_MOTION for kind, *_ in events[2:-1])  # button held throughout
    hops = [math.hypot(bx - ax, by - ay) for (ax, ay), (bx, by) in zip([(10, 20), *motions], motions)]
    assert max(hops) <= _linux_input.DRAG_STEP_PX + 1  # walked, not teleported (+1: rounding)
    assert display.warps == []


def test_drag_walks_through_every_waypoint_in_order(xtest_recorder, monkeypatch) -> None:
    """A freehand-brush stroke: the waypoints must all be visited, in order,
    with the button held, so a canvas draws the curve rather than a chord."""
    monkeypatch.setattr(_linux_input, "DRAG_PACE_S", 0)
    monkeypatch.setattr(_linux_input, "DRAG_THRESHOLD_PAUSE_S", 0)
    monkeypatch.setattr(_linux_input, "DRAG_HOVER_S", 0)
    events, _display = xtest_recorder
    path = [(60, 20), (60, 80), (10, 80)]
    _linux_input.drag(10, 20, 10, 20, path=path)
    assert events[1] == (_X_BPRESS, 1, 0, 0) and events[-1] == (_X_BRELEASE, 1, 0, 0)
    motions = [(x, y) for kind, _d, x, y in events[2:-1] if kind == _X_MOTION]
    seen = [motions.index(p) for p in [*path, (10, 20)]]  # every waypoint is a motion event
    assert seen == sorted(seen)
    assert len(motions) > len(path) + 1  # intermediate hops between waypoints


def test_hops_end_exactly_on_the_target() -> None:
    assert _linux_input._hops(0, 0, 0, 0) == [(0, 0)]
    hops = _linux_input._hops(0, 0, 100, 0)
    assert hops[-1] == (100, 0) and len(hops) == 13


def test_drag_pauses_past_the_gtk_threshold_then_hovers(xtest_recorder, monkeypatch) -> None:
    """A short stroke still walks in small hops. GTK needs a pause once the
    pointer is past the threshold, and a rest on the target before release."""
    import time

    sleeps: list[float] = []
    monkeypatch.setattr(time, "sleep", lambda seconds: sleeps.append(seconds))
    events, _display = xtest_recorder
    _linux_input.drag(0, 0, 0, 28)
    assert events[0] == (_X_MOTION, 0, 0, 0)
    assert events[1] == (_X_BPRESS, 1, 0, 0)
    assert events[-2:] == [(_X_MOTION, 0, 0, 28), (_X_BRELEASE, 1, 0, 0)]
    motions = [(x, y) for kind, _d, x, y in events[2:-1]]
    hops = [abs(by - ay) for (_ax, ay), (_bx, by) in zip([(0, 0), *motions], motions)]
    assert hops and max(hops) <= _linux_input.DRAG_STEP_PX + 1
    # 28px is four hops: 7 (still under the threshold), 14 (past it), 21, 28.
    assert sleeps == [
        _linux_input.DRAG_PACE_S,
        _linux_input.DRAG_THRESHOLD_PAUSE_S,
        _linux_input.DRAG_PACE_S,
        _linux_input.DRAG_HOVER_S,
    ]
    sleeps.clear()
    _linux_input.drag(0, 0, 0, 9)
    assert sleeps == [
        _linux_input.DRAG_PACE_S,
        _linux_input.DRAG_THRESHOLD_PAUSE_S,
        _linux_input.DRAG_HOVER_S,
    ]


def test_drag_below_the_gtk_threshold_does_not_pause(xtest_recorder, monkeypatch) -> None:
    """A slider nudge that never clears the threshold keeps the old short pace."""
    import time

    sleeps: list[float] = []
    monkeypatch.setattr(time, "sleep", lambda seconds: sleeps.append(seconds))
    events, _display = xtest_recorder
    _linux_input.drag(0, 0, 0, 8)
    assert events[-2:] == [(_X_MOTION, 0, 0, 8), (_X_BRELEASE, 1, 0, 0)]
    assert sleeps == [_linux_input.DRAG_PACE_S]
    assert _linux_input.DRAG_THRESHOLD_PAUSE_S not in sleeps
    assert _linux_input.DRAG_HOVER_S not in sleeps


def test_scroll_positions_before_wheel_notches(xtest_recorder) -> None:
    events, display = xtest_recorder
    _linux_input.scroll(100, 200, dy=2, dx=-1)
    assert events[0] == (_X_MOTION, 0, 100, 200)
    assert events[1:5] == [(_X_BPRESS, 5, 0, 0), (_X_BRELEASE, 5, 0, 0)] * 2  # wheel down x2
    assert events[5:] == [(_X_BPRESS, 6, 0, 0), (_X_BRELEASE, 6, 0, 0)]  # horizontal
    assert display.warps == []


class _GermanLayoutDisplay(_FakeXDisplay):
    """The keymap python-xlib reports for a de layout: '@' lives on AltGr+q
    (``keycode 24 = q Q q Q at Greek_OMEGA``), so keysym_to_keycode(0x40) finds
    keycode 24 although neither its base nor its Shift level produces '@'. Records
    keymap changes so a test can see the spare-keycode path being taken."""

    def __init__(self) -> None:
        super().__init__()
        self.keymap = {
            24: [0x71, 0x51, 0x71, 0x51, 0x40, 0x7D9],  # q Q q Q at Greek_OMEGA
            37: [0xFFE3, 0, 0, 0, 0, 0],  # Control_L
            50: [0xFFE1, 0, 0, 0, 0, 0],  # Shift_L
        }
        self.remapped: list[tuple[int, int]] = []  # (keycode, new base keysym)
        self.display = _NS(info=_NS(min_keycode=8, max_keycode=255))

    def keysym_to_keycode(self, keysym):
        return next((kc for kc, syms in self.keymap.items() if keysym in syms), 0)

    def keycode_to_keysym(self, keycode, index):
        syms = self.keymap.get(keycode, [])
        return syms[index] if index < len(syms) else 0

    def get_keyboard_mapping(self, first, count):
        return [self.keymap.get(first + i, [0] * 6) for i in range(count)]

    def change_keyboard_mapping(self, first, keysyms):
        self.remapped.append((first, keysyms[0][0]))
        self.keymap[first] = list(keysyms[0])


def test_altgr_only_keysym_is_typed_through_a_spare_keycode(xtest_recorder, monkeypatch) -> None:
    events, _ = xtest_recorder
    display = _GermanLayoutDisplay()
    monkeypatch.setattr(_linux_input, "_display", display)
    key_press, key_release = 2, 3  # the fake Xlib.X constants installed by the fixture

    # base and Shift levels still map directly; the AltGr-only '@' does not
    assert _linux_input._keycode_and_shift(0x71) == (24, False)
    assert _linux_input._keycode_and_shift(0x51) == (24, True)
    assert _linux_input._keycode_and_shift(0x40) == (None, False)

    _linux_input.type_string("@")
    keys = [(t, d) for t, d, _x, _y in events]
    assert (key_press, 24) not in keys, "typing '@' must not press the q key"
    (spare, bound), (restored, orig) = display.remapped  # bound for the string, then restored
    assert bound == 0x40 and restored == spare and orig == 0 and spare not in (24, 37, 50)
    assert keys == [(key_press, spare), (key_release, spare)]

    events.clear()
    display.remapped.clear()
    _linux_input.press_chord("ctrl+@")
    keys = [(t, d) for t, d, _x, _y in events]
    assert (key_press, 24) not in keys, "ctrl+@ must not become ctrl+q"
    spare = display.remapped[0][0]
    assert keys == [(key_press, 37), (key_press, spare), (key_release, spare), (key_release, 37)]
    assert display.remapped[-1] == (spare, 0)  # the keymap is restored after the chord


@pytest.mark.parametrize("letter,keycode", [("a", 38), ("c", 54), ("z", 52)])
@pytest.mark.parametrize("shift", [False, True])
def test_ctrl_letter_uses_real_key_in_second_layout_group(
    xtest_recorder, monkeypatch, letter, keycode, shift,
) -> None:
    events, _ = xtest_recorder
    display = _GermanLayoutDisplay()
    # ru,us: Cyrillic base/Shift, Latin base/Shift in the second group.
    display.keymap[keycode] = [0x6C6, 0x6E6, ord(letter), ord(letter.upper()), 0, 0]
    monkeypatch.setattr(_linux_input, "_display", display)
    monkeypatch.setattr(_linux_input, "_lock_mask", lambda: (False, False))

    _linux_input.press_chord("ctrl+" + ("shift+" if shift else "") + letter)

    modifiers = [37, 50] if shift else [37]
    assert [(kind, detail) for kind, detail, _x, _y in events] == [
        *[(2, modifier) for modifier in modifiers],
        (2, keycode), (3, keycode),
        *[(3, modifier) for modifier in reversed(modifiers)],
    ]
    assert display.remapped == []

    # Plain typing must still emit the requested Latin character, not Cyrillic.
    events.clear()
    _linux_input.type_string(letter)
    spare = display.remapped[0][0]
    assert display.remapped == [(spare, ord(letter)), (spare, 0)]
    assert [(kind, detail) for kind, detail, _x, _y in events] == [(2, spare), (3, spare)]


def _russian_only_display() -> "_GermanLayoutDisplay":
    """A single ``ru`` group: the Cyrillic letters sit on the physical keys, and no
    key anywhere produces a Latin letter or digit (#1211)."""
    display = _GermanLayoutDisplay()
    display.keymap.pop(24)
    display.keymap.update({
        24: [0x6CA, 0x6EA, 0, 0, 0, 0],  # q position: Cyrillic_shorti
        38: [0x6C6, 0x6E6, 0, 0, 0, 0],  # a position: Cyrillic_ef
        52: [0x6D1, 0x6F1, 0, 0, 0, 0],  # z position: Cyrillic_ya
        54: [0x6D3, 0x6F3, 0, 0, 0, 0],  # c position: Cyrillic_es
        55: [0x6CD, 0x6ED, 0, 0, 0, 0],  # v position: Cyrillic_em
        10: [ord("1"), ord("!"), 0, 0, 0, 0],  # digits stay Latin on ru
        64: [0xFFE9, 0, 0, 0, 0, 0],  # Alt_L
        133: [0xFFEB, 0, 0, 0, 0, 0],  # Super_L
    })
    return display


@pytest.mark.parametrize("chord,mods,keycode", [
    ("ctrl+z", [37], 52),
    ("ctrl+a", [37], 38),
    ("ctrl+c", [37], 54),
    ("ctrl+v", [37], 55),
    ("ctrl+shift+z", [37, 50], 52),
    ("alt+z", [64], 52),
    ("super+q", [133], 24),
])
def test_shortcut_on_a_single_non_latin_layout_presses_the_us_position_key(
    xtest_recorder, monkeypatch, chord, mods, keycode,
) -> None:
    """ru has no Latin z, so ctrl+z must press the physical Z key (keycode 52),
    which Chromium matches by its US-QWERTY position. It must not bind a spare
    keycode to the Latin keysym, which no toolkit treats as the shortcut."""
    events, _ = xtest_recorder
    display = _russian_only_display()
    monkeypatch.setattr(_linux_input, "_display", display)
    monkeypatch.setattr(_linux_input, "_lock_mask", lambda: (False, False))

    with _linux_input.physical_position_target(lambda: True):  # a Chromium target
        _linux_input.press_chord(chord)

    assert [(kind, detail) for kind, detail, _x, _y in events] == [
        *[(2, m) for m in mods], (2, keycode), (3, keycode), *[(3, m) for m in reversed(mods)],
    ]
    assert display.remapped == []
    assert _linux_input.take_mismatch() is None


@pytest.mark.parametrize("target", ["non-chromium", "unknown", "resolver-raises"])
@pytest.mark.parametrize("chord", ["ctrl+z", "ctrl+shift+a", "alt+c"])
def test_shortcut_for_gtk_or_an_unknown_target_keeps_the_spare_keycode_path(
    xtest_recorder, monkeypatch, target, chord,
) -> None:
    """#1211 follow-up: GTK/Qt ignore the physical keycode on a lone ru layout and
    honour a spare keycode carrying the Latin keysym. Only Chromium gets the US position."""
    events, _ = xtest_recorder
    display = _russian_only_display()
    monkeypatch.setattr(_linux_input, "_display", display)
    monkeypatch.setattr(_linux_input, "_lock_mask", lambda: (False, False))

    def boom() -> bool:
        raise RuntimeError("no accessibility bus")

    resolver = {"non-chromium": lambda: False, "resolver-raises": boom}.get(target)
    if resolver is None:
        _linux_input.press_chord(chord)
    else:
        with _linux_input.physical_position_target(resolver):
            _linux_input.press_chord(chord)

    keysym = ord(chord[-1])
    assert len(display.remapped) == 2 and display.remapped[0][1] == keysym
    spare = display.remapped[0][0]
    pressed = [detail for kind, detail, _x, _y in events if kind == 2]
    assert spare in pressed
    assert not {52, 38, 54} & set(pressed)


def test_target_is_asked_once_and_only_when_the_layout_needs_it(
    xtest_recorder, monkeypatch,
) -> None:
    events, _ = xtest_recorder
    asked: list[str] = []

    def resolver() -> bool:
        asked.append("asked")
        return True

    ru = _russian_only_display()
    monkeypatch.setattr(_linux_input, "_display", ru)
    monkeypatch.setattr(_linux_input, "_lock_mask", lambda: (False, False))
    with _linux_input.physical_position_target(resolver):
        _linux_input.press_chord("ctrl+1")   # a Latin key exists: no question
        _linux_input.press_chord("Return")
        assert asked == []
        _linux_input.press_chord("ctrl+z")
    assert asked == ["asked"]


class _SelectionText:
    """The slice of ``Atspi.Text`` that a select-all check reads."""

    def __init__(self, count, selected):
        self.count, self.selected = count, selected

    def get_character_count(self, acc):
        return self.count

    def get_caret_offset(self, acc):
        return self.count

    def get_n_selections(self, acc):
        return 0 if self.selected is None else 1

    def get_selection(self, acc, index):
        return self.selected


def _ru_with_backspace():
    display = _russian_only_display()
    display.keymap[22] = [0xFF08, 0, 0, 0, 0, 0]  # BackSpace
    return display


def _select_all_world(monkeypatch, *, chromium, state):
    """Internal chords on a lone ru layout, with a field whose selection is ``state``."""
    from types import SimpleNamespace

    monkeypatch.setattr(_linux_input, "_lock_mask", lambda: (False, False))
    monkeypatch.setattr(_atspi, "_atspi", lambda: SimpleNamespace(Text=state))
    monkeypatch.setattr(_atspi, "_chromium_app", lambda acc: chromium)
    monkeypatch.setattr(_atspi, "grab_focus", lambda acc: True)
    monkeypatch.setattr(_atspi, "_confirm_focus_on_target", lambda acc: True)
    monkeypatch.setattr(_atspi, "_focus_on_target", lambda acc: True)
    monkeypatch.setattr(_atspi, "_SELECT_ALL_PAUSE_S", 0)


@pytest.mark.parametrize("chromium,keycode", [(True, 38), (False, None)])
def test_internal_select_all_uses_the_physical_key_only_for_chromium(
    xtest_recorder, monkeypatch, chromium, keycode,
) -> None:
    """#1225: set_value's clear sends ctrl+a through _chord_into_target, not through
    LinuxDriver.key_chord, so it needs the same Chromium-only physical key."""
    events, _ = xtest_recorder
    display = _russian_only_display()
    monkeypatch.setattr(_linux_input, "_display", display)
    _select_all_world(monkeypatch, chromium=chromium, state=_SelectionText(7, (0, 7)))
    _atspi._chord_into_target(object(), "ctrl+a")
    pressed = [detail for kind, detail, _x, _y in events if kind == 2]
    if keycode is not None:
        assert pressed == [37, keycode] and display.remapped == []
    else:
        assert 38 not in pressed and len(display.remapped) == 2  # the spare keycode, as before


def test_a_dropped_select_all_never_sends_backspace(xtest_recorder, monkeypatch) -> None:
    """#1225: Ctrl+A selected nothing and BackSpace then ate 'me' from 'keep me'."""
    events, _ = xtest_recorder
    monkeypatch.setattr(_linux_input, "_display", _ru_with_backspace())
    _select_all_world(monkeypatch, chromium=True, state=_SelectionText(7, None))
    with pytest.raises(ComputerUseError) as exc:
        _atspi._x11_select_all_and_delete(object())
    assert exc.value.detail["reason"] == "selection_unconfirmed"
    assert "nothing was deleted" in str(exc.value)
    assert 22 not in [detail for kind, detail, _x, _y in events]  # no BackSpace


