def test_large_panel_preserves_its_painted_children(fake_atspi) -> None:
    panel = _Acc("panel", states=("SHOWING",), width=1414920272, height=22043)
    app = _NS(get_toolkit_name=lambda: "GTK", get_toolkit_version=lambda: "4.18.6")
