@pytest.mark.parametrize("owner_name", ["kate", "Kate"])
def test_kate_status_controls_survive_without_document_viewport_probe(
    fake_atspi, monkeypatch, owner_name,
) -> None:
    """KTextEditor viewport reads must not disrupt the later status-bar walk."""
    app = _Acc("application", name=owner_name)
    app.get_toolkit_name = lambda: "Qt"
    editor = _Acc("text", name="document.txt", width=700, height=400,
                  states={"MULTI_LINE", "EDITABLE"})
    editor.text = "TOP\nOFFSCREEN_TOKEN"
    names = ("1:1", "INSERT", "Soft Tabs: 4", "UTF-8", "Normal", "Output", "Diagnostics", "Search")
    controls = [
        _Acc("push button menu" if name in {"UTF-8", "Normal"} else
             "check box" if name in {"Output", "Diagnostics", "Search"} else
             "push button", name=name, width=80, height=23)
        for name in names
    ]
    status = _adopt(_Acc("panel", width=700, height=23), *controls)
    window = _adopt(_Acc("frame", name="document.txt", width=800, height=600),
                    editor, status)
    _adopt(app, window)
    for node in (window, editor, status, *controls):
        node.get_application = lambda: app
    monkeypatch.setattr(_atspi, "_state_flags",
                        lambda acc: (True, False, None, False, None, True, True))

    def disruptive_probe(node):
        # Model the live Qt bridge: a viewport request makes later children
        # unavailable. This is unnecessary because Kate's value is refused.
        status.children.clear()
        return "TOP"

    monkeypatch.setattr(_atspi, "_qt_viewport_text", disruptive_probe)
    snap = build_snapshot(window, _atspi.ATSPIAccessor(), scope=Scope.WINDOW,
                          app=owner_name, pid=646, geometry=_geometry())
    for name in names:
        found = observe.find_elements(snap, text=name)
        assert len(found) == 1
        assert found[0].title == name
        assert found[0].ref
    document, = observe.find_elements(snap, role="textarea")
    assert document.value is None
    assert "in-document Find" in document.hint
    assert not observe.find_elements(snap, text="OFFSCREEN_TOKEN")
    assert editor.text == "TOP\nOFFSCREEN_TOKEN"


@pytest.mark.parametrize("side,role", [("wrapper", "entry"), ("child", "entry"),
                                       ("child", "text"), ("ordinary", "entry")])
def test_gtk4_password_entry_boundary_classified_before_text_reads(monkeypatch, side, role):
    """Native password ancestry/children establish the early refusal."""
    acc, password = object(), object()
    monkeypatch.setattr(_atspi, "_role_name", lambda n: "password text" if n is password else role)
    monkeypatch.setattr(_atspi, "_call_first", lambda *a, **k: None)
    monkeypatch.setattr(_atspi, "_state_flag", lambda *a, **k: False)
    monkeypatch.setattr(_atspi, "_get_attributes", lambda n: {"toolkit": "GTK"})
    monkeypatch.setattr(_atspi, "_toolkit_version", lambda n: "4.0")
    monkeypatch.setattr(_atspi, "_parent_of", lambda n: password if side == "child" else None)
    monkeypatch.setattr(_atspi, "_child_count", lambda n: 1 if side == "wrapper" else 0)
    monkeypatch.setattr(_atspi, "_child_at", lambda n, index: password)
    class Text:
        @staticmethod
        def get_string_at_offset(*args):
            assert side == "ordinary", "password boundary must not read Text"
            return type("Rendered", (), {"content": ""})()
        @staticmethod
        def get_character_count(*args):
            return 0
    api = type("API", (), {"Text": Text, "TextGranularity": type("Granularity", (), {"LINE": 0})})
    monkeypatch.setattr(_atspi, "_atspi", lambda: api)
    assert _atspi.is_secure(acc) is (side != "ordinary")


def test_geany_fixture_initializes_caret_until_native_status_is_ready() -> None:
    """Welcome text is not caret evidence; setup stops before tested actions."""
    from types import SimpleNamespace
    from tests.test_linux_live import _geany_initial_line

    calls = []
    driver = SimpleNamespace(
        activate_app=lambda app: calls.append(("activate", app)),
        key_chord=lambda chord: calls.append(("key", chord)),
    )
    bar = SimpleNamespace(role="AXStatusBar", title="This is Geany 2.0.", value=None)
    snap = SimpleNamespace(elements=(bar,))
    assert not _geany_initial_line(driver, snap)
    assert calls == [("activate", "geany"), ("key", "ctrl+Home")]
    # An editor buffer containing the phrase cannot establish readiness.
    bar.role = "AXTextArea"
    bar.title = "line: 1 / 303"
    assert not _geany_initial_line(driver, snap)
    bar.role = "AXStatusBar"
    calls.clear()
    assert _geany_initial_line(driver, snap)
    assert calls == []


@pytest.mark.parametrize("role_name", ["slider", "spin button", "progress bar", "level bar"])
@pytest.mark.parametrize("garbage", [0.0, 6.9e-310, 40.0])
def test_range_observation_never_reads_a_missing_value_interface(
    fake_atspi, monkeypatch, role_name, garbage,
):
    """Missing Value can return even another widget's valid number (#619)."""
    node = _Acc(role_name, value=garbage)
    node.get_value_iface = lambda: None
    reads = []

    def unexpected_read(acc):
        reads.append(acc)
        return garbage

    for method in ("get_current_value", "get_minimum_value", "get_maximum_value"):
        monkeypatch.setattr(fake_atspi.Value, method, unexpected_read)
    assert _atspi._value_text(node, _atspi._ROLE[role_name], role_name) is None
    assert reads == []


