@pytest.mark.parametrize("role", ["slider", "spin button"])
@pytest.mark.parametrize("case", ["relation", "row", "named", "non_gtk", "missing", "tie", "other_row", "right"])
def test_gtk_numeric_controls_use_stable_labels(fake_atspi, monkeypatch, role, case):
    """Native labels survive changing values; unavailable row evidence stays unnamed."""
    monkeypatch.setattr(_atspi, "_toolkit_name", lambda node: "qt" if case == "non_gtk" else "gtk")
    control = _place_row(_Acc(role, name="Native" if case == "named" else "", value=8,
                              states=("ENABLED", "VISIBLE", "SHOWING")),
                         200, 100, 140, 30)
    control.get_description = lambda: f"{control.value:g} px" if role == "slider" else ""
    label = _place_row(_Acc("label", name="Threshold:"),
                       350 if case == "right" else 20,
                       200 if case == "other_row" else 105, 160, 20)
    _adopt(_Acc("panel"), control, label)
    # Exercise the real relation reader; relation evidence does not need geometry.
    relation = _NS(get_relation_type=lambda: "labelled-by", get_n_targets=lambda: 1,
                   get_target=lambda index: label)
    control.get_relation_set = lambda: [relation] if case in {"relation", "named", "non_gtk"} else []
    if case in {"missing", "relation"}:
        control.component = None
    if case == "tie":
        other = _place_row(_Acc("label", name="Other:"), 20, 105, 160, 20)
        _adopt(control.parent, control, label, other)
    accessor = _atspi.ATSPIAccessor()
    for value in (8, 10, 6):
        control.value = value
        raw = accessor.read(control)
        assert raw.title == ("Threshold" if case in {"relation", "row"} else
                             "Native" if case == "named" else "")
        assert raw.value == value
        assert raw.description == (f"{value} px" if role == "slider" else "")
        if case in {"relation", "row"}:
            snap = build_snapshot(control, accessor, scope=Scope.WINDOW,
                                  app="demo", pid=639, geometry=_geometry())
            assert len(observe.find_elements(snap, text="Threshold")) == 1


@pytest.mark.parametrize("identifier", ["vlc", "VLC media player"])
@pytest.mark.parametrize("registration", ["missing", "ready", "retry"])
def test_vlc_registration_probe_is_bounded(fake_atspi, monkeypatch, identifier, registration):
    """Young VLC must fail quickly, but a real root always remains usable."""
    from a11y_computer_use.drivers import _linux_system

    clock = {"t": 0.0}
    probes = []
    window = _Acc("frame", name="VLC", width=640, height=480)

    def find_root(name, scope):
        probes.append(name)
        if registration == "ready" or (registration == "retry" and clock["t"] > 0):
            return window
        return None

    monkeypatch.setattr(_atspi, "find_root", find_root)
    monkeypatch.setattr(_atspi, "raise_if_app_stopped", lambda app: None)
    monkeypatch.setattr(_atspi, "app_listed", lambda app: True)
    monkeypatch.setattr(_linux_system, "resolve_app", lambda app: "vlc")
    monkeypatch.setattr(_linux_system, "pids_matching", lambda app: {123})
    monkeypatch.setattr(_atspi, "process_age_s", lambda pid: 1.0 + clock["t"])
    monkeypatch.setattr(_atspi, "primary_geometry", _geometry)
    monkeypatch.setattr(_atspi, "_screen_size", lambda: (1280, 800))
    monkeypatch.setattr("a11y_computer_use.drivers.linux.time.monotonic", lambda: clock["t"])
    monkeypatch.setattr("a11y_computer_use.drivers.linux.time.sleep",
                        lambda seconds: clock.__setitem__("t", clock["t"] + seconds))
    driver = LinuxDriver()
    for _ in range(2):
        before = clock["t"]
        probes.clear()
        if registration == "missing":
            with pytest.raises(ComputerUseError) as exc:
                driver.snapshot(Scope.WINDOW, identifier)
            assert exc.value.code is ErrorCode.UNSUPPORTED
            assert exc.value.detail["reason"] == "no_accessibility_bridge"
            assert "QT_LINUX_ACCESSIBILITY_ALWAYS_ON=1" in exc.value.detail["hint"]
            assert "restart VLC" in exc.value.detail["hint"]
        else:
            snap = driver.snapshot(Scope.WINDOW, identifier)
            assert snap.elements[0].role == "AXWindow"
            assert snap.elements[0].title == "VLC"
        assert clock["t"] - before < 0.5
        assert len(probes) <= 4


@pytest.mark.parametrize("failure", ["marshalling", "exception", "timeout", "no_answer", "malformed", "empty_content", "invalid_content"])
@pytest.mark.parametrize("read_path", ["bounded", "sentinel", "chunks", "unavailable"])
def test_qt_failed_ranges_recover_native_text(monkeypatch, failure, read_path):
    """A broken QSpiTextRangeList must still reach working Text reads."""
    text = "QTDOC_684 hello" + "x" * 300
    reads = []
    checked = []
    monkeypatch.setattr(_atspi, "_raw_rect", lambda *args: (20, 30, 800, 400))

    def ranges(*args):
        if failure == "marshalling":
            raise RuntimeError("Marshalling failed: Unregistered type QSpiTextRangeList")
        if failure == "exception":
            raise ValueError("invalid D-Bus reply")
        if failure == "timeout":
            raise TimeoutError("Did not receive a reply")
        if failure == "empty_content":
            return [_NS(content="")]
        if failure == "invalid_content":
            return [_NS(content=None)]
        return [object()] if failure == "malformed" else None

    def get_text(acc, start, end):
        reads.append((start, end))
        if read_path == "unavailable":
            raise RuntimeError("Text unavailable")
        if read_path == "sentinel" and end != -1:
            raise RuntimeError("Explicit range failed")
        if read_path == "chunks" and (end == -1 or end - start > 256):
            raise RuntimeError("Large range failed")
        return text[start:] if end == -1 else text[start:end]

    def rectangle(acc, offset, coord):
        checked.append(offset)
        return _NS(x=20, y=40 if offset < 15 else 900, width=8, height=16)

    monkeypatch.setattr(_atspi, "_atspi", lambda: _NS(
        CoordType=_NS(SCREEN=0), TextClipType=_NS(BOTH=3),
        Text=_NS(get_bounded_ranges=ranges,
                 get_offset_at_point=lambda *args: -1,
                 get_character_count=lambda acc: len(text),
                 get_text=get_text, get_character_extents=rectangle),
    ))
    value = _atspi._qt_viewport_text(object())
    if read_path == "unavailable":
        assert value is None
        assert checked == []
    else:
        assert value == text[:15]
        assert checked == list(range(len(text)))
        raw = RawNode(role="AXTextArea", value=value)
        snap = build_snapshot((raw, []), _FakeAccessor(), scope=Scope.WINDOW,
                              app="scribus", pid=1, geometry=_geometry())
        assert observe.find_elements(snap, text="QTDOC_684")
    assert reads[0] == (0, len(text))
    if read_path == "sentinel":
        assert reads == [(0, len(text)), (0, -1)]
    elif read_path in {"chunks", "unavailable"}:
        assert reads[:3] == [(0, len(text)), (0, -1), (0, 256)]
        assert len(reads) <= 4


@pytest.mark.parametrize("chunk_failure", [False, True])
def test_qt_range_recovery_never_requests_unbounded_large_document(monkeypatch, chunk_failure):
    text = "QTDOC_684 hello" + "x" * _atspi._PAGE_TEXT_CHARS
    reads = []
    monkeypatch.setattr(_atspi, "_raw_rect", lambda *args: (20, 30, 800, 400))

    def get_text(acc, start, end):
        reads.append((start, end))
        assert end != -1
        assert 0 <= start <= end <= _atspi._PAGE_TEXT_CHARS
        if end - start > 256 or (chunk_failure and start > 0):
            raise RuntimeError("Range read failed")
        return text[start:end]

    def ranges(*args):
        raise RuntimeError("Unregistered type QSpiTextRangeList")

    monkeypatch.setattr(_atspi, "_atspi", lambda: _NS(
        CoordType=_NS(SCREEN=0), TextClipType=_NS(BOTH=3),
        Text=_NS(get_bounded_ranges=ranges,
                 get_offset_at_point=lambda *args: -1,
                 get_character_count=lambda acc: len(text), get_text=get_text,
                 get_character_extents=lambda *args: _NS(x=20, y=40, width=8, height=16)),
    ))
    value = _atspi._qt_viewport_text(object())
    if chunk_failure:
        assert value is None
    else:
        assert value == text[:_atspi._PAGE_TEXT_CHARS]
    assert len(reads) <= 1 + (_atspi._PAGE_TEXT_CHARS + 255) // 256


def test_qt_unanswered_bounded_ranges_clears_libatspi_hang_before_reading(monkeypatch):
    """#684: Scribus never answers GetBoundedRanges (QSpiTextRangeList is not
    registered). libatspi then reports the app as hung until its pending
    replies are dispatched; the editor text must still be read afterwards."""
    text = "Hello Scribus 12345"
    hung = {"on": False}
    drained = []
    monkeypatch.setattr(_atspi, "_raw_rect", lambda *args: (150, 150, 460, 237))

    def guarded(fn):
        def call(*args):
            if hung["on"]:
                raise RuntimeError("atspi_error: The process appears to be hung. (1)")
            return fn(*args)
        return call

    def bounded(*args):
        hung["on"] = True
        raise RuntimeError("atspi_error: Did not receive a reply.")

    def drain(*args, **kwargs):
        drained.append(True)
        hung["on"] = False

    monkeypatch.setattr(_atspi, "_drain_atspi_replies", drain)
    monkeypatch.setattr(_atspi, "_atspi", lambda: _NS(
        CoordType=_NS(SCREEN=0), TextClipType=_NS(BOTH=3),
        Text=_NS(
            get_bounded_ranges=bounded,
            get_offset_at_point=guarded(lambda *args: -1),
            get_character_count=guarded(lambda acc: len(text)),
            # Qt returns "" for an end offset past the character count.
            get_text=guarded(lambda acc, start, end: (
                text if end == -1 else ("" if end > len(text) else text[start:end]))),
            get_character_extents=guarded(
                lambda acc, offset, coord: _NS(x=155 + 8 * offset, y=155, width=8, height=17)),
        ),
    ))
    value = _atspi._qt_viewport_text(object())
    assert drained == [True]
    assert value == text
    raw = RawNode(role="AXTextArea", value=value)
    snap = build_snapshot((raw, []), _FakeAccessor(), scope=Scope.WINDOW,
                          app="scribus", pid=1, geometry=_geometry())
    assert observe.find_elements(snap, text="Scribus 123")


def test_qt_answered_bounded_ranges_does_not_drain(monkeypatch):
    drained = []
    monkeypatch.setattr(_atspi, "_raw_rect", lambda *args: (20, 30, 800, 400))
    monkeypatch.setattr(_atspi, "_drain_atspi_replies", lambda *a, **k: drained.append(True))
    monkeypatch.setattr(_atspi, "_atspi", lambda: _NS(
        CoordType=_NS(SCREEN=0), TextClipType=_NS(BOTH=3),
        Text=_NS(get_bounded_ranges=lambda *args: [_NS(content="VISIBLE")]),
    ))
    assert _atspi._qt_viewport_text(object()) == "VISIBLE"
    assert drained == []


@pytest.mark.parametrize("fail", [False, True])
def test_top_level_enumeration_bypasses_stale_application_children(
    fake_atspi, monkeypatch, fail,
) -> None:
    """A new Story Editor is discovered despite a persistent native child cache."""
    from a11y_computer_use.drivers import _atspi_events, _linux_system

    main = _WindowNode("frame", "Scribus", states={"SHOWING"})
    editor = _WindowNode("frame", "Story Editor - Text1", states={"SHOWING", "ACTIVE"})
    app = _WindowNode("application", "scribus", children=[main, editor])
    desktop = _WindowNode("desktop", children=[app])
    fake_atspi.desktop = desktop
    for node in (app, main, editor):
        node.get_application = lambda: app
    masks = []
    state = {"mask": 1}

    def set_mask(mask):
        masks.append(mask)
        state["mask"] = mask

    def count():
        if state["mask"] == 0:
            return 2
        return 1

    def child(index):
        if state["mask"] == 0 and index == 1:
            if fail:
                raise RuntimeError("native read failed")
            return editor
        return main

    app.set_cache_mask = set_mask
    app.get_child_count = count
    app.get_child_at_index = child
    monkeypatch.setattr(_atspi, "_cache_masks", lambda: (0, 1))
    monkeypatch.setattr(_atspi_events, "run", lambda fn: fn())
    monkeypatch.setattr(_linux_system, "pids_matching", lambda app: set())
    monkeypatch.setattr(_linux_system, "active_window", lambda: None)
    monkeypatch.setattr(_atspi, "_combo_owning_popup", lambda node: None)
    monkeypatch.setattr(_atspi, "_state_has", lambda node, name: name in node.states)
    # The native StateSet path used by find_root, rather than names fallback.
    active = object()
    monkeypatch.setattr(fake_atspi.StateType, "ACTIVE", active, raising=False)
    for node in (main, editor):
        node.get_state_set = lambda node=node: _NS(
            contains=lambda flag: flag == active and "ACTIVE" in node.states,
        )
    with _atspi.read_cache():
        assert _atspi._child_count(app) == 1
        picked = _atspi.find_root("scribus", Scope.WINDOW)
        assert picked is (main if fail else editor)
        assert _atspi.snapshot_window_list(main) == ([main] if fail else [editor, main])
    assert masks
    assert masks == [0, 1] * (len(masks) // 2)
    assert state["mask"] == 1


def test_calc_viewport_bands_are_explicitly_synthetic(fake_atspi, monkeypatch) -> None:
    """The native sheet stays distinct from snapshot-only cell groups."""
    monkeypatch.setattr(_atspi, "_screen_size", lambda: (1280, 800))
    table = _calc_grid(fake_atspi)
    try:
        accessor = _atspi.ATSPIAccessor()
        bands = accessor.children(table)
        assert len(bands) > 1
        assert all(isinstance(band, _atspi._OnScreenBand) for band in bands)
        native_cells = _atspi._sheet_window_cells(table)
        assert [cell for band in bands for cell in accessor.children(band)] == native_cells
        snap = _sheet_snapshot(table)
        tables = [el for el in snap.elements if el.role == "AXTable"]
        assert len(tables) == len(bands) + 1
        assert tables[0].title == "Sheet"
        assert all(el.title == "Visible cells (synthetic viewport band)" for el in tables[1:])
        assert 'table "Visible cells (synthetic viewport band)"' in observe.render_text(snap, mode="full")
        assert len([el for el in snap.elements if el.role == "AXCell"]) == 29 * 16
        found = observe.find_elements(snap, text="A29")
        assert len(found) == 1 and found[0].bounds is not None
    finally:
        del fake_atspi.Table


