@pytest.mark.parametrize("window_role,app_name", [("window", "xfce4-notifyd"),
                                                 ("notification", "notification-daemon")])
@pytest.mark.parametrize("phase", ["activation", "feedback"])
@pytest.mark.parametrize("change", ["alive", "expired", "defunct", "detached", "moved",
                                    "missing_state", "missing_hit", "replacement", "cached",
                                    "missing_bounds", "bus_error"])
def test_notification_ref_click_rechecks_after_preparation(
    monkeypatch, window_role, app_name, phase, change,
):
    from contextlib import nullcontext
    from a11y_computer_use.drivers import linux, _atspi_events
    from a11y_computer_use.schema import MouseButton

    target = _GeckoNode("push button", "Okay", ("SHOWING", "VISIBLE"))
    window = _GeckoNode(window_role, "T", ("SHOWING", "VISIBLE"), (target,))
    app = _GeckoNode("application", app_name)
    app.toolkit = "GTK"
    target.application = window.application = app
    rect = _NS(x=10, y=10, width=100, height=40)
    hit = [target]
    window.get_component_iface = lambda: _NS(
        get_extents=lambda coord: _NS(x=0, y=0, width=200, height=100),
        get_accessible_at_point=lambda *a: hit[0],
    )
    target.get_component_iface = lambda: _NS(get_extents=lambda coord: rect)
    monkeypatch.setattr(_atspi, "_atspi", lambda: _NS(CoordType=_NS(SCREEN=0)))
    # Exercise native cache invalidation with cached SHOWING surviving expiry.
    monkeypatch.setattr(_atspi_events, "listening", lambda: True)
    monkeypatch.setattr(_atspi_events, "run", lambda fn: fn())
    expired = []
    target.clear_cache_single = lambda: target.states.clear() if expired else None
    element = Element("e1", "AXButton", "Okay", None, Bounds(0, 10, 10, 100, 40),
                      "notification-race", clickable=True)
    observe._register_epoch(element.snapshot_id, {}, {element.ref: target})
    driver = LinuxDriver()
    monkeypatch.setattr(driver, "_run", lambda fn: fn())
    monkeypatch.setattr(linux, "_on_wayland", lambda: False)
    monkeypatch.setattr(driver, "_visible_action", lambda *a: None)
    monkeypatch.setattr(_linux_input, "held", lambda mods: nullcontext())
    clicks = []
    monkeypatch.setattr(_linux_input, "click", lambda *a, **kw: clicks.append((a, kw)))

    def prepare(handle):
        assert handle is target
        if change == "expired":
            window.states.clear()
        elif change == "defunct":
            target.states.add("DEFUNCT")
        elif change == "detached":
            target.parent = None
        elif change == "moved":
            rect.x = 300
        elif change == "missing_state":
            target.get_state_set = lambda: None
        elif change == "missing_hit":
            hit[0] = None
        elif change == "replacement":
            hit[0] = _GeckoNode("push button", "Okay", ("SHOWING", "VISIBLE"))
        elif change == "cached":
            expired.append(True)
        elif change == "missing_bounds":
            rect.width = 0
        elif change == "bus_error":
            def unavailable():
                raise RuntimeError("notification service disappeared")
            target.get_state_set = unavailable

    monkeypatch.setattr(driver, "_raise_handle_window",
                        prepare if phase == "activation" else lambda *a: None)
    if phase == "feedback":
        monkeypatch.setattr(driver, "_visible_action", lambda *a: prepare(target))
    if change == "alive":
        driver.click(element, button=MouseButton.RIGHT, count=2, modifiers=("shift",))
        assert clicks == [((60, 30), {"button": "right", "count": 2})]
    else:
        with pytest.raises(ComputerUseError) as exc:
            driver.click(element)
        assert exc.value.code == ErrorCode.STALE_REF
        assert exc.value.detail["reason"] == "notification_target_unverified"
        assert exc.value.detail["outcome"] == "refused"
        assert clicks == []
    assert not target.pressed


@pytest.mark.parametrize("cached_old_app", [False, True])
@pytest.mark.parametrize("scope", [Scope.APP, Scope.WINDOW])
def test_find_root_refreshes_registry_after_calc_restart(
    fake_atspi, monkeypatch, cached_old_app, scope,
) -> None:
    """A stale desktop list must not hide the replacement Calc registrant."""
    from a11y_computer_use.drivers import _atspi_events, _linux_system

    old = _WindowNode("application", "soffice")
    sheet = _WindowNode("frame", "Untitled 1 - LibreOffice Calc")
    replacement = _WindowNode("application", "soffice", children=[sheet])
    desktop = _WindowNode("desktop")
    fake_atspi.desktop = desktop
    cached = [old] if cached_old_app else []
    mask = {"value": 1}
    changes = []

    def set_mask(value):
        changes.append(value)
        mask["value"] = value

    desktop.set_cache_mask = set_mask
    desktop.get_child_count = lambda: len(cached) if mask["value"] else 1
    desktop.get_child_at_index = lambda i: cached[i] if mask["value"] else replacement
    monkeypatch.setattr(_atspi, "_cache_masks", lambda: (0, 1))
    monkeypatch.setattr(_atspi_events, "run", lambda fn: fn())
    monkeypatch.setattr(_linux_system, "pids_matching", lambda app: set())
    monkeypatch.setattr(_linux_system, "active_window", lambda: None)
    with _atspi.read_cache():
        # Seed the operation cache too; native cache bypass alone is insufficient.
        assert _atspi._child_count(desktop) == len(cached)
        assert _atspi.find_root("soffice", scope) is (
            replacement if scope is Scope.APP else sheet
        )
    assert changes == [0, 1]
    assert mask["value"] == 1


@pytest.mark.parametrize("action", ["click", "press"])
@pytest.mark.parametrize("change", ["unchanged", "renamed", "unreadable", "role_changed"])
@pytest.mark.parametrize("version", ["", "2.24.33", "3.24.49", "4.18.6"])
def test_gtk_cell_rechecks_cached_label_after_preparation(fake_atspi, monkeypatch, action, change, version):
    from contextlib import nullcontext
    from a11y_computer_use.drivers import linux, _atspi_events
    from a11y_computer_use.schema import MouseButton

    cell = _GeckoNode("table cell", "A00GONE 7", ("SHOWING", "VISIBLE"))
    app = _GeckoNode("application", "xfce4-taskmanager")
    app.toolkit = "GTK"
    app.get_toolkit_version = lambda: version
    cell.application = app
    cell.actions = ["activate"]
    element = Element("e1", "AXCell", "A00GONE 7", None, Bounds(0, 10, 10, 100, 40),
                      "recycled-gtk-cell", clickable=True)
    observe._register_epoch(element.snapshot_id, {}, {element.ref: cell})
    driver = LinuxDriver()
    monkeypatch.setattr(driver, "_run", lambda fn: fn())
    monkeypatch.setattr(_atspi_events, "run", lambda fn: fn())
    monkeypatch.setattr(linux, "_on_wayland", lambda: False)
    monkeypatch.setattr(driver, "_refuse_hidden", lambda *a: None)
    monkeypatch.setattr(driver, "_visible_action", lambda *a: None)
    monkeypatch.setattr(_linux_input, "held", lambda mods: nullcontext())
    clicks = []
    monkeypatch.setattr(_linux_input, "click", lambda *a, **kw: clicks.append((a, kw)))
    prepared = []
    monkeypatch.setattr(driver, "_raise_handle_window", lambda *a: prepared.append(True))

    def clear():
        assert prepared
        if change == "renamed":
            cell.name = "A11YPROBE0640 3000"
        elif change == "unreadable":
            cell.get_name = lambda: None
        elif change == "role_changed":
            cell.role = "push button"

    cell.clear_cache_single = clear
    # Cache the issued label in both layers. Only native invalidation reveals
    # the replacement, and operation-local invalidation must expose that read.
    with _atspi.read_cache():
        assert _atspi._call_first(cell, ("get_name",)) == element.title

        def invoke():
            if action == "press":
                return driver.press_element(element)
            return driver.click(element, button=MouseButton.RIGHT, count=2, modifiers=("shift",))

        if change == "unchanged":
            invoke()
            if action == "click":
                assert clicks == [((60, 30), {"button": "right", "count": 2})]
            else:
                assert cell.pressed
        else:
            with pytest.raises(ComputerUseError) as exc:
                invoke()
            assert exc.value.code == ErrorCode.STALE_REF
            assert exc.value.detail["reason"] == "target_changed"
            assert exc.value.detail["outcome"] == "refused"
            assert clicks == []
            assert not cell.pressed


@pytest.mark.parametrize("verify", [False, True])
def test_gtk_flat_table_click_reports_selection_only(
    fake_atspi, monkeypatch, xtest_recorder, tmp_path, verify
) -> None:
    """A GTK theme-list selection is not evidence of row-activated (#929)."""
    from a11y_computer_use import observe, safety, server

    events, _display = xtest_recorder
    cell = _outline_cell("Adwaita-dark", ["expand or contract", "edit", "activate"])
    window = _outline_window(cell, role="table")
    driver = _wire_gtk_tree(monkeypatch, window)
    monkeypatch.setattr(server, "_running_app", lambda name: (None, name))
    monkeypatch.setattr(safety, "seconds_since_user_input", lambda: None)
    actions = []
    cell.do_action = lambda index: actions.append(index) or True
    shot = driver.snapshot(Scope.WINDOW, "outline")
    store = safety.PermissionStore(tmp_path / "permissions.json")
    store.set_tier(shot.app or "outline", safety.Tier.FULL)
    runtime = server.Runtime(
        store=store, audit=safety.AuditLog(tmp_path / "audit"), driver=driver,
    )
    runtime._current = shot
    runtime._recheck_target = lambda *_args, **_kwargs: None
    target = next(el for el in shot.elements if el.title == "Adwaita-dark")
    note = "single click selects only; activation may require count=2"
    assert target.note == note
    assert note in observe.render_matches(shot, (target,))
    events.clear()
    result = runtime.click(target.ref, verify=verify)
    assert note in result
    assert result.outcome == "unverifiable"
    assert result.next == ()
    assert "re-observe first" in result.evidence
    assert result.evidence.startswith("row activation is not verified; single click selects only")
    assert "SELECTED" in cell.states
    assert actions == []
    assert not [event for event in events if event[0] == _X_BPRESS]

    runtime._current = driver.snapshot(Scope.WINDOW, "outline")
    target = next(el for el in runtime._current.elements if el.title == "Adwaita-dark")
    events.clear()
    double = runtime.click(target.ref, count=2)
    assert note not in double
    assert len([event for event in events if event[0] == _X_BPRESS]) == 2
    assert actions == []


