@pytest.mark.parametrize("parent_role", ["document web", "section"])
@pytest.mark.parametrize("change", ["append", "replace"])
def test_chromium_snapshot_includes_children_added_after_list_probe(
    fake_atspi, monkeypatch, parent_role, change,
):
    """A timer can publish a toast between list discovery and the main walk."""
    from a11y_computer_use.drivers import _atspi_events

    button = _Acc("push button", name="Send", width=80, height=30,
                  states={"SHOWING"})
    old = _Acc("static", name="Old message", width=160, height=30,
               states={"SHOWING"})
    toast = _Acc("static", name="Toast shown", width=160, height=30,
                 states={"SHOWING"})
    parent = _adopt(_Acc(parent_role, width=1000, height=700,
                         states={"SHOWING"}), button, old)
    document = parent if parent_role == "document web" else _adopt(
        _Acc("document web", width=1000, height=700, states={"SHOWING"}), parent,
    )
    document.name = "Ready"
    window = _adopt(_Acc("frame", name="Chrome", width=1000, height=700), document)
    app = _adopt(_Acc("application", name="chrome"), window)
    app.get_toolkit_name = lambda: "Chrome"
    for node in (app, window, document, parent, button, old, toast):
        node.get_application = lambda: app
    monkeypatch.setattr(_atspi_events, "run", lambda fn: fn())
    driver = _wire_gtk_tree(monkeypatch, window)
    before = driver._snapshot_root("chrome", window, Scope.WINDOW)
    discover = _atspi._list_containers

    def discover_then_publish(root):
        found = discover(root)
        # The native tree changes without an AT-SPI mutator in this process.
        if change == "append":
            _adopt(parent, button, old, toast)
        else:
            _adopt(parent, button, toast)
        document.name = "Shown"
        return found

    monkeypatch.setattr(_atspi, "_list_containers", discover_then_publish)
    after = driver._snapshot_root("chrome", window, Scope.WINDOW)
    assert "Shown" in {el.title for el in after.elements}
    delta = observe.diff_snapshots(before, after)
    assert "Toast shown" in {el.title for el in delta.added}
    assert "Toast shown" in observe.render_diff(delta)
    if change == "replace":
        assert "Old message" in {el.title for el in delta.removed}


@pytest.mark.parametrize("frame_showing", [False, True])
@pytest.mark.parametrize("labels", [("Reload Ctrl+R",), ("New tab Ctrl+T", "New window Ctrl+N", "Help")])
def test_chrome_native_popup_menu_snapshot(fake_atspi, monkeypatch, frame_showing, labels):
    """#966: native menu geometry survives an empty top-level wrapper."""
    page = _Acc("frame", name="Page - Google Chrome", width=800, height=600,
                states=("SHOWING", "ACTIVE"))
    popup = _Acc("frame", states=("SHOWING",) if frame_showing else ())
    menu = _Acc("menu", width=240, height=120, states=("SHOWING", "VISIBLE"))
    items = [_Acc("menu item", name=label, width=240, height=30,
                  states=("SHOWING", "VISIBLE", "ENABLED", "SENSITIVE")) for label in labels]
    for index, item in enumerate(items):
        _place_row(item, 100, 100 + index * 30, 240, 30)
    _place_row(menu, 100, 100, 240, 120)
    _adopt(menu, *items)
    _adopt(popup, menu)
    cached = _Acc("frame", states=("SHOWING",))
    app = _adopt(_Acc("application", name="Google Chrome"), page, cached, popup)
    for node in (app, page, cached, popup, menu, *items):
        node.get_application = lambda: app
    driver = _wire_gtk_tree(monkeypatch, page)
    assert _atspi.snapshot_window_list(page) == [page, menu]
    assert _atspi.chromium_snapshot_root(menu) is menu
    snap = driver.snapshot(Scope.WINDOW, "Google Chrome")
    found = observe.find_elements(snap, role="menuitem")
    assert [el.title for el in found] == list(labels)
    for element, native in zip(found, items):
        assert element.clickable and element.ref
        assert element.bounds == Bounds(0, 100, 100 + items.index(native) * 30, 240, 30)
        assert observe.ax_handle_for(element.snapshot_id, element.ref) is native
    menu.states.clear()
    assert menu not in _atspi.snapshot_window_list(page)


@pytest.mark.parametrize("with_text_child", [False, True], ids=["native-popup", "aria"])
def test_tooltips_retain_native_role_in_find(fake_atspi, monkeypatch, with_text_child):
    """#969: native tool tip nodes survive mapping and shared pruning."""
    title = "Ships in 3–5 business days"
    tip = _Acc("tool tip", name=title, width=175, height=24,
               states=("SHOWING", "VISIBLE", "ENABLED", "SENSITIVE"))
    _place_row(tip, 100, 100, 175, 24)
    if with_text_child:
        text = _Acc("static", name=title, width=175, height=24,
                    states=("SHOWING", "VISIBLE"))
        _place_row(text, 100, 100, 175, 24)
        _adopt(tip, text)
    group = _Acc("panel", name="Ordinary group", width=200, height=50,
                 states=("SHOWING", "VISIBLE"))
    frame = _adopt(_Acc("frame", name="Page", width=800, height=600,
                       states=("SHOWING", "VISIBLE")), tip, group)
    original_value_text = _atspi._value_text

    def value_text(node, *args, **kwargs):
        assert node is not tip, "Tooltips must not gain Text/Value probes"
        return original_value_text(node, *args, **kwargs)

    monkeypatch.setattr(_atspi, "_value_text", value_text)
    snap = build_snapshot(frame, _atspi.ATSPIAccessor(), scope=Scope.WINDOW,
                          app="chrome", pid=1, geometry=_geometry())
    match, = observe.find_elements(snap, role="tooltip")
    assert match.role == "AXTooltip"
    assert match.title == title
    assert match.value is None
    assert match.bounds == Bounds(0, 100, 100, 175, 24)
    assert not match.clickable
    assert observe.ax_handle_for(snap.snapshot_id, match.ref) is tip
    assert 'tooltip "Ships in 3–5 business days"' in observe.render_text(snap)
    ordinary, = observe.find_elements(snap, role="group", text="Ordinary group")
    assert ordinary.role == "AXGroup"


@pytest.mark.parametrize("showing", [True, False])
@pytest.mark.parametrize("nested", [True, False])
def test_chromium_multi_item_list_keeps_overflow_controls(
    fake_atspi, monkeypatch, showing, nested,
):
    """Synthetic CSS dropdown: item bounds do not clip its painted children."""
    app = _ChromeApp()
    window = _Acc("frame", name="Dropdown", width=1280, height=800)
    document = _Acc("document web", states=("SHOWING",), width=1200, height=680)
    listing = _Acc("list", width=220, height=35)
    plain = _Acc("list item", width=100, height=35)
    parent = _Acc("list item", width=120, height=35)
    plain_text = _Acc("static", name="Plain", width=80, height=16)
    parent_text = _Acc("static", name="Products", width=90, height=16)
    link = _Acc("link", name="Downloads", width=140, height=30,
                states=("VISIBLE", "SHOWING") if showing else ("VISIBLE",))
    submenu = _Acc("list", width=142, height=32)
    item = _Acc("list item", width=140, height=30)
    _adopt(window, document)
    _adopt(document, listing)
    _adopt(listing, plain, parent)
    _adopt(plain, plain_text)
    _adopt(parent, parent_text, submenu if nested else link)
    _adopt(submenu, item)
    if nested:
        _adopt(item, link)
    nodes = [window, document, listing, plain, parent, plain_text, parent_text,
             submenu, item, link]
    _own(app, *nodes)
    for node, x, y, w, h in (
        (document, 0, 90, 1200, 680), (listing, 24, 212, 220, 35),
        (plain, 24, 212, 100, 35), (parent, 124, 212, 120, 35),
        (plain_text, 30, 220, 80, 16), (parent_text, 130, 220, 90, 16),
        (submenu, 124, 247, 142, 32), (item, 125, 248, 140, 30),
        (link, 125, 248, 140, 30),
    ):
        _place_row(node, x, y, w, h)
    _wire_chrome_list(monkeypatch, window, _ListHit([], []), stuck=True)
    snap = LinuxDriver().snapshot(Scope.WINDOW, "chrome")
    matches = observe.find_elements(snap, text="Downloads", role="link")
    if not showing:
        assert not matches
        return
    assert len(matches) == 1
    assert matches[0].bounds == Bounds(0, 125, 248, 140, 30)
    assert "Downloads" in observe.render_text(snap)
    assert observe.ax_handle_for(snap.snapshot_id, matches[0].ref) is link
    runtime = _runtime_for(LinuxDriver(), monkeypatch)
    monkeypatch.setattr(runtime.driver, "ensure_trusted", lambda: None)
    monkeypatch.setattr(_linux_input, "scroll", lambda *a, **k: pytest.fail("visible link must not scroll"))
    assert "Downloads" in runtime.scroll_to_find("chrome", text="Downloads", role="link")


