def test_native_control_identity_survives_rename_and_flattening(fake_atspi, monkeypatch):
    """Retain the bus/object key, not the title or a transient Python proxy."""
    monkeypatch.setattr(_atspi, "_state_flags", lambda acc: (True, False, None, False, None, False, False))
    monkeypatch.setattr(_atspi, "_extents", lambda acc, keep_zero=False: ((10., 40.), (150., 25.)))
    key = [(':1.2', '/accessible/42')]
    monkeypatch.setattr(_atspi, "_atspi_wrapper_key", lambda acc: key[0])
    for name, expected in [("Count 0", key[0]), ("Count 1", key[0]), ("Count 2", ())]:
        if not expected:
            key[0] = None
        raw = _atspi.ATSPIAccessor().read(_Acc("push button", name=name))
        snap = build_snapshot((raw, []), _FakeAccessor(), scope=Scope.WINDOW,
                              app="chrome", pid=1, geometry=_geometry())
        assert raw.node_identity == expected
        assert snap.elements[0].node_identity == expected
        assert snap.elements[0].title == name


def test_snapshot_50k_rows_never_queries_collection(fake_atspi, monkeypatch):
    """Modal discovery must not materialize rows omitted by the snapshot walk."""
    window, table, _, _ = _large_gtk_tree(rows=50000)
    driver = _wire_gtk_tree(monkeypatch, window)
    monkeypatch.setattr(driver, "_run", lambda fn: fn())
    queries = []
    reads = []

    class Collection:
        def get_matches(self, *args):
            queries.append(args)
            return []

    def collection(node):
        queries.append(node)
        return Collection()
    monkeypatch.setattr(_Acc, "get_collection_iface", collection, raising=False)
    native_child = _Acc.get_child_at_index
    def child(node, index):
        reads.append((node, index))
        return native_child(node, index)
    monkeypatch.setattr(_Acc, "get_child_at_index", child)
    native_cell = table.get_accessible_at
    def cell(row, col):
        reads.append((row, col))
        return native_cell(row, col)
    table.get_accessible_at = cell
    for _ in range(2):
        reads.clear()
        snap = driver.snapshot(Scope.WINDOW, "treeprobe")
        assert queries == []
        assert "ROW-00000" in _gtk_row_titles(snap)
        assert "ROW-00019" in _gtk_row_titles(snap)
        assert len(reads) <= 10 * len(snap.elements)


@pytest.mark.parametrize("length", [199, 200, 201, 1000])
@pytest.mark.parametrize("mismatch", [False, True])
def test_type_outcome_compares_full_target_text(monkeypatch, length, mismatch):
    """A clipped preview cannot turn a verified long write into partial."""
    from a11y_computer_use import server

    requested = "α" * (length - 1) + "Z"
    actual = requested[:-1] + "X" if mismatch else requested
    snap = build_snapshot(
        _node("AXTextArea", "Editor", value=actual, actions=("set_value",)),
        _FakeAccessor(), scope=Scope.WINDOW, app="editor", pid=1,
        geometry=_geometry(),
    )
    element = snap.elements[0]
    driver = LinuxDriver()
    monkeypatch.setattr(driver, "_run", lambda fn: fn())
    monkeypatch.setattr(_atspi, "_text_security", lambda handle: (False,))
    reads = []

    def read(handle):
        assert handle is observe.ax_handle_for(element.snapshot_id, element.ref)
        reads.append(handle)
        return actual

    monkeypatch.setattr(_atspi, "_readable_text", read)
    runtime = server.Runtime.__new__(server.Runtime)
    runtime.driver = driver
    monkeypatch.setattr(runtime, "_reread", lambda *args: snap)
    monkeypatch.setattr(runtime, "_process_died", lambda before: False)
    monkeypatch.setattr(runtime, "_remember_baseline", lambda after: None)
    verdict, evidence = runtime._judge_mutation(
        "editor", None, element, requested, previous="",
    )
    assert verdict == ("partial" if mismatch else "confirmed"), evidence
    assert bool(reads) == (length > 200)
    assert element.value == (actual[:199] + "…" if length > 200 else actual)


