@pytest.mark.parametrize("modal_open", [False, True])
def test_gtk_model_modal_guard_checks_sibling_without_reading_rows(fake_atspi, monkeypatch, modal_open):
    """A cold GTK TreeView must remain clickable without querying its model."""
    window, table, _, _ = _large_gtk_tree(rows=20000)
    button = _Acc("push button", name="Apply selection")
    button.parent = window
    window.children.append(button)
    modal = _Acc("dialog", name="Confirm", states=("SHOWING", "MODAL"))
    application = _adopt(_Acc("application", name="treeprobe"), window,
                         *([modal] if modal_open else []))
    table.get_child_count = lambda: pytest.fail("modal discovery read virtual GTK rows")
    table.get_collection_iface = lambda: pytest.fail("modal discovery queried virtual GTK rows")
    assert _atspi.active_modals(window) == ([modal] if modal_open else [])
    if modal_open:
        with pytest.raises(ComputerUseError, match="outside_active_modal"):
            _atspi.refuse_outside_modal(button, window)
        assert _atspi.refuse_outside_modal(modal, application)
    else:
        assert _atspi.refuse_outside_modal(button, window) is False


@pytest.mark.parametrize("points", [0, 18, 40])
def test_drag_modal_probe_latency_is_independent_of_path(
    modal_boundary_tree, monkeypatch, points,
):
    """#1053: model the reported 150 ms native probe, without clock jitter."""
    from a11y_computer_use.schema import Drag
    driver, frame, bg, modal, inside, calls = modal_boundary_tree
    frame.children.remove(modal)
    elapsed = 0.0
    discoveries = []
    original = _atspi.active_modals
    def discover(root, **kwargs):
        nonlocal elapsed
        elapsed += 0.15
        discoveries.append(root)
        return original(root, **kwargs)
    monkeypatch.setattr(_atspi, "active_modals", discover)
    hits = []
    def hit(x, y):
        hits.append((x, y))
        return bg
    monkeypatch.setattr(_atspi, "_accessible_at_point", hit)
    start, end = Point(0, 100, 110), Point(0, 200, 110)
    path = tuple(Point(0, 101 + i, 110) for i in range(points))
    driver.check_modal_input(Drag(start, end, path=path), "modal-test")
    # The remaining 1.2 s stroke/readback budget must still fit 1.5 s.
    assert 1.2 + elapsed <= 1.5
    assert len(discoveries) == 2
    assert hits == [(100, 110), (200, 110)]


@pytest.mark.parametrize("outside", ["source", "target"])
@pytest.mark.parametrize("by_ref", [False, True])
def test_drag_modal_endpoints_still_refuse_background(
    modal_boundary_tree, monkeypatch, outside, by_ref,
):
    from a11y_computer_use.schema import Drag
    driver, frame, bg, modal, inside, calls = modal_boundary_tree
    modal.states.remove("MODAL")
    modal.get_attributes = lambda: {"aria-modal": "true"}
    snap = driver.snapshot(Scope.WINDOW, "modal-test")
    if by_ref:
        background = next(el for el in snap.elements if el.title == bg.name)
        foreground = next(el for el in snap.elements if el.title == inside.name)
    else:
        background, foreground = Point(0, 100, 110), Point(0, 350, 225)
        monkeypatch.setattr(_atspi, "_accessible_at_point",
                            lambda x, y: bg if x == 100 else inside)
    monkeypatch.setattr("a11y_computer_use.drivers.linux.time.sleep", lambda _: None)
    start, end = ((background, foreground) if outside == "source"
                  else (foreground, background))
    with pytest.raises(ComputerUseError, match="outside_active_modal"):
        driver.check_modal_input(Drag(start, end), "modal-test")
    assert calls == []
    frame.children.remove(modal)
    driver.check_modal_input(Drag(start, end), "modal-test")


@pytest.mark.parametrize("text", ["E7\n", "F5", "E7\r\n"])
def test_opaque_office_toolbar_type_avoids_cell_verification(fake_atspi, monkeypatch, text):
    """Opaque Name Box input is dispatched once, without grid reads/writes."""
    from a11y_computer_use.drivers import linux

    toolbar = _Acc("tool bar", name="Formula Tool Bar")
    panel = _Acc("panel", states=("FOCUSED",))
    _adopt(toolbar, panel)
    monkeypatch.setattr(_atspi, "_focused_node", lambda *a, **kw: (panel, False))
    monkeypatch.setattr(_atspi, "_readable_text", lambda acc: None)
    monkeypatch.setattr(_atspi, "focused_editable", lambda app: None)
    monkeypatch.setattr(_atspi, "note_focused_find_bar", lambda app: None)
    monkeypatch.setattr(linux, "_on_wayland", lambda: False)
    sent = []
    monkeypatch.setattr(_linux_input, "type_string", sent.append)
    for name in ("drawing_focus_text", "sheet_editor_text", "spreadsheet_open",
                 "sheet_grid_check", "poll_sheet_type", "_commit_open_sheet_editor",
                 "note_focused_find_bar", "focused_chromium_entry"):
        monkeypatch.setattr(_atspi, name, lambda *a, **kw: pytest.fail("unrelated document probe"))
    driver = LinuxDriver()
    driver._run = lambda fn: fn()
    driver.frontmost_app = lambda: ("soffice.bin", 1)
    checks = []
    driver._refuse_xtest_password_focus = lambda: checks.append(True)
    normalized = text.replace("\r\n", "\n")
    assert driver.type_text(text) == len(normalized)
    assert sent == [normalized]
    assert checks == [True]
    assert driver._opaque_toolbar_type == ("soffice.bin", normalized)
    assert driver._sheet_type_origin is None


