def test_chromium_search_burst_keeps_each_notch_synced(xtest_recorder, monkeypatch):
    events, _display = xtest_recorder
    timeline = []
    monkeypatch.setattr(_linux_input, "_flush", lambda: timeline.append(("sync", len(events))))
