@pytest.mark.parametrize("ownership", ["relation", "transient"])
def test_window_modal_blocks_only_its_parent(modal_boundary_tree, monkeypatch, ownership):
    from a11y_computer_use.drivers import _linux_system
    from a11y_computer_use.schema import Click, TypeText, KeyChord

    driver, frame, bg, modal, inside, calls = modal_boundary_tree
    other = _Acc("frame", name="Other document", states=("SHOWING", "ACTIVE", "ENABLED"))
    _adopt(frame, bg)
    app = _adopt(_Acc("application"), frame, other, modal)
    monkeypatch.setattr(_atspi, "pid_of", lambda node: 321)
    relation = _NS(get_relation_type=lambda: "subwindow-of", get_n_targets=lambda: 1,
                               get_target=lambda index: other)
    modal.get_relation_set = lambda: [relation] if ownership == "relation" else []
    monkeypatch.setattr(_linux_system, "transient_parent_title", lambda **kw: (
        other.name if ownership == "transient" and kw == {"pid": 321, "title": modal.name} else None))
    monkeypatch.setattr(_atspi, "_fresh_application_children", lambda node: list(node.children))
    monkeypatch.setattr(_atspi, "_focused_node", lambda app: (bg, frame))
    monkeypatch.setattr(_atspi, "_accessible_at_point", lambda *args: bg)

    snap = driver.snapshot(Scope.WINDOW, "modal-test")
    target = next(el for el in snap.elements if el.title == bg.name)
    assert target.clickable and not target.blocked_by_modal
    assert _atspi.active_modals(frame) == []
    assert not _atspi.outside_modals(bg, [modal], cache={})
    assert driver.press_element(target)
    assert calls == [bg.name]
    for action, addressed in ((Click(target), None), (Click(Point(0, 100, 110)), None),
                              (TypeText("ok"), target), (TypeText("ok"), None),
                              (KeyChord("ctrl+End"), None)):
        driver.check_modal_input(action, "modal-test", input_target=addressed)

    # Move the reported ownership to this document; no stale snapshot/cache may
    # authorize background input. Preserve the #1013 refusal on every attempt.
    relation.get_target = lambda index: frame
    monkeypatch.setattr(_linux_system, "transient_parent_title", lambda **kw: frame.name)
    for _ in range(3):
        snap = driver.snapshot(Scope.WINDOW, "modal-test")
        target = next(el for el in snap.elements if el.title == bg.name)
        assert target.blocked_by_modal and not target.actionable
        for invoke in (lambda: driver.press_element(target),
                       lambda: driver.set_value(target, "blocked"),
                       lambda: driver.type_into(target, "blocked"),
                       lambda: driver.check_modal_input(Click(Point(0, 100, 110)), "modal-test"),
                       lambda: driver.check_modal_input(TypeText("blocked"), "modal-test"),
                       lambda: driver.check_modal_input(KeyChord("ctrl+End"), "modal-test")):
            with pytest.raises(ComputerUseError, match="outside_active_modal"):
                invoke()
    assert calls == [bg.name]
    assert not _atspi.outside_modals(inside, [modal])
    assert modal.parent is app


@pytest.mark.parametrize("path", [
    b"/org/a11y/atspi/accessible/7",
    b"/org/gtk/application/unknown/a11y/4c3cfe47_a3d2_4ae2_b040_37921f9e4e35",
    b"/org/example/Editor/a11y/7",
])
def test_native_ref_identity_accepts_gtk4_application_paths(monkeypatch, path):
    """#1130: GTK4 paths must supply real bus/object continuity for rebinding."""
    import ctypes

    object_type, application_type = _atspi._atspi_identity_layouts()
    application = application_type()
    application.bus_name = b":1.42"
    native = object_type()
    native.app = ctypes.addressof(application)
    native.path = path
    monkeypatch.setattr(_atspi, "_gobject_pointer", lambda handle: ctypes.addressof(native))
    assert _atspi._atspi_wrapper_key(object()) == (":1.42", path.decode())
    application.bus_name = b":1.43"
    assert _atspi._atspi_wrapper_key(object()) == (":1.43", path.decode())
    application.bus_name = b""
    assert _atspi._atspi_wrapper_key(object()) is None
    application.bus_name = b":1.42"
    native.path = b""
    assert _atspi._atspi_wrapper_key(object()) is None


@pytest.mark.parametrize("exposed", [False, True])
def test_unexposed_native_message_box_blocks_only_its_parent_refs(
    modal_boundary_tree, monkeypatch, exposed,
):
    """#1146: Electron's showMessageBox(win) is an X11-only GTK modal."""
    from a11y_computer_use.drivers import _linux_system
    from a11y_computer_use.schema import Click, KeyChord, TypeText

    driver, frame, bg, modal, inside, calls = modal_boundary_tree
    frame.children.remove(modal)  # No AT-SPI modal: the box has no accessible.
    unrelated = _Acc("frame", name="Other", states=("SHOWING",))
    other_button = _outline_cell("Other Action", ["press"])
    other_button.role = "push button"
    _adopt(unrelated, other_button)
    children = [frame, unrelated]
    if exposed:
        children.append(_Acc("dialog", name="Confirm Change", states=("SHOWING",)))
    application = _adopt(_Acc("application", name="electron"), *children)
    for node in (application, frame, bg, unrelated, other_button, *children):
        node.get_application = lambda: application
    monkeypatch.setattr(_atspi, "pid_of", lambda node: 321)
    monkeypatch.setattr(_atspi, "_fresh_application_children", lambda node: list(node.children))
    box = {"window_id": 0x600003, "title": "Confirm Change",
           "bounds": {"display_id": 0, "x": 550, "y": 410, "width": 180, "height": 83}}
    open_box = [True]
    probes = []

    def windows(*, pid, parent_title):
        probes.append((pid, parent_title))
        return [box] if open_box[0] and pid == 321 and parent_title == frame.name else []

    monkeypatch.setattr(_linux_system, "transient_modal_windows", windows)
    snap = driver.snapshot(Scope.WINDOW, "modal-test")
    background = next(el for el in snap.elements if el.title == bg.name)
    dialogs = [el for el in snap.elements if el.title == "Confirm Change"]
    if exposed:
        # A modal transient AT-SPI exposes stays with the reported-state guards.
        assert not [el for el in dialogs if el.role == "AXDialog" and el.content_note]
        assert not background.blocked_by_modal
        driver.press_element(background)
        assert calls == [bg.name]
        return
    assert len(dialogs) == 1 and dialogs[0].modal and dialogs[0].role == "AXDialog"
    assert not dialogs[0].clickable and dialogs[0].bounds.width == 180
    assert "outside the accessibility tree" in dialogs[0].content_note
    assert background.blocked_by_modal and not background.clickable
    assert "outside_active_modal" in observe.render_matches(snap, (background,))
    for invoke in (
        lambda: driver.press_element(background),
        lambda: driver.set_value(background, "banana"),
        lambda: driver.type_into(background, "zz"),
        lambda: driver.check_modal_input(Click(background), "modal-test"),
        lambda: driver.check_modal_input(TypeText("zz"), "modal-test", input_target=background),
    ):
        with pytest.raises(ComputerUseError, match="outside_active_modal") as caught:
            invoke()
        assert "Confirm Change" in str(caught.value)
        assert caught.value.detail["modal_windows"][0]["window_id"] == 0x600003
    assert calls == []
    # Keys and coordinate clicks follow native routing and can answer the box.
    driver.check_modal_input(KeyChord("ctrl+l"), "modal-test")
    driver.check_modal_input(TypeText("y"), "modal-test")
    monkeypatch.setattr(_atspi, "_accessible_at_point", lambda *args: bg)
    monkeypatch.setattr("a11y_computer_use.drivers.linux.time.sleep", lambda _: None)
    driver.check_modal_input(Click(Point(0, 600, 450)), "modal-test")
    # Another window of the same app is not owned by the box (#1139/#1140).
    assert _atspi.unexposed_native_modals(unrelated) == []
    _atspi.refuse_unexposed_native_modal(other_button)
    # Closing the box restores input with no cached refusal.
    open_box[0] = False
    restored = driver.snapshot(Scope.WINDOW, "modal-test")
    again = next(el for el in restored.elements if el.title == bg.name)
    assert not again.blocked_by_modal
    assert not [el for el in restored.elements if el.title == "Confirm Change"]
    driver.press_element(again)
    assert calls == [bg.name]


def test_unexposed_native_modal_probe_is_one_x11_pass_and_skips_non_windows(fake_atspi, monkeypatch):
    from a11y_computer_use.drivers import _linux_system
    calls = []
    monkeypatch.setattr(_linux_system, "transient_modal_windows",
                        lambda **kw: calls.append(kw) or [])
    monkeypatch.setattr(_atspi, "pid_of", lambda node: 321)
    monkeypatch.setattr(_atspi, "_fresh_application_children",
                        lambda node: pytest.fail("no AT-SPI read without an X11 modal"))
    frame = _Acc("frame", name="Main", states=("SHOWING",))
    button = _adopt(frame, _Acc("push button", name="Go")).children[0]
    assert _atspi.unexposed_native_modals(frame) == []
    _atspi.refuse_unexposed_native_modal(button)
    assert calls == [{"pid": 321, "parent_title": "Main"}] * 2
    assert _atspi.unexposed_native_modals(_Acc("panel", name="Main")) == []
    assert _atspi.unexposed_native_modals(None) == []
    assert len(calls) == 2


@pytest.mark.parametrize("container", ["dialog", "alert", "document web"])
def test_gecko_select_in_dialog_closes_popup_without_escape(fake_atspi, monkeypatch, container):
    """#1150: a collapsed Firefox select inside a dialog gets no Escape.

    Firefox 158 keeps the option menu SHOWING under a modal ``<dialog>`` or
    ARIA dialog while the select is collapsed. That is not an open popup, so
    no Escape is sent: four of them closed the dialog. Outside a dialog the
    SHOWING menu still counts, and an EXPANDED select inside one still closes.
    """
    from a11y_computer_use.drivers import _linux_input

    menu = _Acc("menu", states=("SHOWING", "VISIBLE"))
    select = _adopt(_Acc("combo box", states=("SHOWING", "FOCUSED")), menu)
    _adopt(_Acc("frame"), _adopt(_Acc(container), select))
    monkeypatch.setattr(_atspi, "_gecko_app", lambda node: True)
    monkeypatch.setattr(_atspi, "_x11_keys_available", lambda: True)
    monkeypatch.setattr(_atspi, "_do_action_named", lambda *a, **k: False)
    monkeypatch.setattr(_atspi.time, "sleep", lambda s: None)
    keys = []
    monkeypatch.setattr(_linux_input, "press_chord", lambda chord: keys.append(chord))
    _atspi._close_combo_popup(select)
    if container == "document web":
        assert keys == ["Escape"] * 4
    else:
        assert keys == []
        select.states.add("EXPANDED")

        def press(chord):
            keys.append(chord)
            select.states.discard("EXPANDED")

        monkeypatch.setattr(_linux_input, "press_chord", press)
        _atspi._close_combo_popup(select)
        assert keys == ["Escape"]


@pytest.fixture
def terminal_scrollback(fake_atspi, monkeypatch):
    """Thirty visible VTE rows with a sibling Value bar; no native desktop."""
    from dataclasses import replace

    terminal, bar, _horizontal = _scrolled_text()
    terminal.role = "terminal"
    bar.minimum, bar.maximum, bar.visual_max, bar.value = 0, 373, 373, 373
    calls = []

    def paint():
        terminal.text = "\n".join(f"LINE-{i:04}" for i in range(int(bar.value) + 1, int(bar.value) + 31))

    def write(acc, value):
        calls.append(value)
        acc.value = value
        paint()
        return True

    paint()
    bar.on_value = write
    driver = LinuxDriver()
    monkeypatch.setattr(driver, "_run", lambda fn: fn())
    monkeypatch.setattr(driver, "ensure_trusted", lambda: None)
