def test_chrome_select_option_click_waits_for_late_expanded_clear(fake_atspi, monkeypatch):
    """Flake in test_linux_chrome_optgroup_select_click_closes_the_popup.

    Chrome can clear the select's EXPANDED state a beat after the popup has
    closed. After the close attempts, the state is re-read for a bounded time
    with no further keys, so a late collapse is not reported as popup_open.
    """
    from a11y_computer_use.drivers import _linux_input

    item = _Acc("menu item", name="Lemon")
    menu = _adopt(_Acc("menu"), item)
    select = _adopt(_Acc("combo box", states=("SHOWING", "EXPANDED")), menu)
    _adopt(_Acc("frame"), _adopt(_Acc("document web"), select))
    monkeypatch.setattr(_atspi, "_gecko_app", lambda node: False)
    monkeypatch.setattr(_atspi, "_chromium_control", lambda node: True)
    monkeypatch.setattr(_atspi, "_x11_keys_available", lambda: True)
    monkeypatch.setattr(_atspi, "_do_action_named", lambda *a, **k: False)
    keys, sleeps = [], []
    monkeypatch.setattr(_linux_input, "press_chord", lambda chord: keys.append(chord))

    def sleep(seconds):
        sleeps.append(seconds)
        if len(sleeps) == 6:  # the collapse lands after the 4 close attempts
            select.states.discard("EXPANDED")

    monkeypatch.setattr(_atspi.time, "sleep", sleep)
    _atspi.finish_chrome_select_option_click(item)
    assert keys == ["Escape"] * 4
    assert sum(sleeps) <= 0.8


def test_chromium_tree_band_keeps_nested_items_under_their_rows(fake_atspi, monkeypatch):
    """#1168: an 8-level Chrome ARIA tree listed 36 rows instead of 8.

    Collection discovery (#1043) let the tree's in-view band take every
    nested treeitem as a direct tree child, so each subtree was emitted
    again. Only the tree's own rows may be re-parented. Synthetic chain.
    """
    tree = _Acc("tree", name="Files", width=400, height=200)
    chain = []
    parent = tree
    for depth in range(1, 9):
        item = _Acc("tree item", name="F" + ".1" * depth, width=400, height=16)
        if parent is tree:
            _adopt(tree, item)
        else:
            group = _Acc("panel")
            _adopt(parent, group)
            _adopt(group, item)
        chain.append(item)
        parent = item
    sibling = _Acc("tree item", name="F.2", width=400, height=16)
    # _adopt replaces children: the tree owns both F.1 and F.2.
    _adopt(tree, chain[0], sibling)
    band = [(acc, (12, 100 + 16 * i), (400, 12)) for i, acc in enumerate(chain + [sibling])]
    monkeypatch.setattr(_atspi, "_chromium_app", lambda node: True)
    monkeypatch.setattr(_atspi, "_list_containers", lambda root: [tree])
    monkeypatch.setattr(_atspi, "_shown_or_probe", lambda container: list(band))
    accessor = _atspi.ATSPIAccessor()
    accessor.refresh_visible(_Acc("frame"))
    assert accessor._visible_children[id(tree)] == [chain[0], sibling]
    assert id(chain[1]) not in accessor._visible_bounds


def test_chromium_collection_timeout_waits_for_the_app_before_walking(fake_atspi, monkeypatch):
    """#1169: a 10,000-button Chrome page came back as one disabled window.

    The native role query timed out after 300ms while Chrome kept filling
    the document, so every walk read that followed also timed out. After a
    timed-out query the app must answer a ping before the walk, and list
    discovery must not ask that app's Collection again. Synthetic doubles.
    """
    roles = _NS(**{name: name for name in (
        "LIST", "LIST_BOX", "TABLE", "TREE", "TREE_TABLE",
        "DIALOG", "ALERT", "WINDOW", "FRAME", "FILE_CHOOSER")})
    api = _NS(Role=roles, StateSet=_NS(new=lambda states: states),
              CollectionMatchType=_NS(NONE=0, ANY=1),
              CollectionSortOrder=_NS(CANONICAL=0),
              MatchRule=_NS(new=lambda *args: args))
    monkeypatch.setattr(_atspi, "_atspi", lambda: api)
    monkeypatch.setattr(_atspi, "_COLLECTION_TIMED_OUT", set())
    window = _Acc("frame")
    monkeypatch.setattr(_atspi, "_atspi_wrapper_key", lambda node: (":1.9", "/w") if node is window else None)
    events = []
    def query(*args):
        events.append("query")
        raise RuntimeError("timeout from dbind")
    window.get_collection_iface = lambda: _NS(get_matches=query)
    monkeypatch.setattr(_atspi, "_ping_answers", lambda node: events.append(("ping", node)) or True)
    _atspi._list_containers(window)
    assert events == ["query", ("ping", window)]
    events.clear()
    _atspi._list_containers(window)
    assert "query" not in events
    events.clear()
    assert _atspi._modal_collection(window) is None
    assert events == ["query", ("ping", window)]


def test_chromium_tree_with_one_own_row_skips_the_hit_probe(fake_atspi, monkeypatch):
    """#1168 perf: a cold 8-level Chrome tree snapshot was 2.3x 0.4.76.

    Collection discovery (#1043) now finds the tree, which has one own row
    and seven nested ones. The band filter keeps only own rows, so a tree
    with fewer than two can never be banded, yet each cold snapshot spent
    ~0.9s hit-testing it. No probe may run for it. A tree with two own rows
    is still banded through the probe, and wrappers between the tree and
    its rows are opened while counting. Synthetic chain.
    """
    tree = _Acc("tree", name="Files", width=400, height=200)
    parent = tree
    for depth in range(1, 9):
        item = _Acc("tree item", name="F" + ".1" * depth, width=400, height=16)
        if parent is tree:
            _adopt(tree, item)
        else:
            group = _Acc("panel")
            _adopt(parent, group)
            _adopt(group, item)
        parent = item
    probed = []

    def probe(container):
        probed.append(container)
        return []

    monkeypatch.setattr(_atspi, "_chromium_app", lambda node: True)
    monkeypatch.setattr(_atspi, "_list_containers", lambda root: [tree])
    monkeypatch.setattr(_atspi, "_shown_or_probe", probe)
    accessor = _atspi.ATSPIAccessor()
    accessor.refresh_visible(_Acc("frame"))
    assert probed == []
    assert id(tree) not in accessor._visible_children

    wrapped = _Acc("tree", name="Two", width=400, height=200)
    section = _Acc("panel")
    _adopt(wrapped, section)
    own = [_Acc("tree item", name=f"R{i}", width=400, height=16) for i in (1, 2)]
    _adopt(section, *own)
    band = [(acc, (12, 100 + 16 * i), (400, 12)) for i, acc in enumerate(own)]
    monkeypatch.setattr(_atspi, "_list_containers", lambda root: [wrapped])
    monkeypatch.setattr(_atspi, "_shown_or_probe", lambda c: probed.append(c) or list(band))
    accessor.refresh_visible(_Acc("frame"))
    assert probed == [wrapped]
    assert accessor._visible_children[id(wrapped)] == own


