def test_a_bound_name_is_not_rebound_to_a_different_program(fake_atspi, monkeypatch) -> None:
    """#1191 pin: ``Files`` bound to Nautilus; Nautilus closes, Thunar is app_not_running."""
    from a11y_computer_use.drivers import _atspi_events

    nautilus_win = _WindowNode("frame", "Home")
    _PidNode("application", "Nautilus", pid=11, children=[nautilus_win])
    restarted_win = _WindowNode("frame", "Home")
    _PidNode("application", "Nautilus", pid=13, children=[restarted_win])
    thunar_win = _WindowNode("frame", "Downloads")
    _PidNode("application", "Thunar", pid=12, children=[thunar_win])
    current = {"root": nautilus_win}
    monkeypatch.setattr(_atspi_events, "run", lambda fn: fn())
    monkeypatch.setattr(_atspi, "find_root", lambda name, scope: current["root"])
    _programs_by_pid(monkeypatch, {11: "nautilus", 12: "thunar", 13: "nautilus"})
    driver = LinuxDriver()
    assert driver._root_for_snapshot("files", Scope.WINDOW) == ("files", nautilus_win)
    current["root"] = restarted_win  # the same program restarted binds again
    assert driver._root_for_snapshot("files", Scope.WINDOW) == ("files", restarted_win)
    current["root"] = thunar_win
    with pytest.raises(ComputerUseError) as exc:
        driver._root_for_snapshot("files", Scope.WINDOW)
    assert exc.value.detail["reason"] == "app_not_running"
    assert exc.value.detail["bound"] == "nautilus"


def test_live_window_contexts_lists_every_published_window_and_never_guesses(monkeypatch):
    """#1215: an unfocused window is still live; unknown is None, not "destroyed"."""
    class Window:
        def __init__(self, role, key):
            self.role, self.key = role, key

    main = Window("frame", (":1.5", "/window/1"))
    other = Window("frame", (":1.5", "/window/2"))
    popup = Window("menu", (":1.5", "/menu/1"))
    app = object()
    children = [main, other, popup]
    monkeypatch.setattr(_atspi, "find_root", lambda name, scope: app if name == "wizard" else None)
    monkeypatch.setattr(_atspi, "_fresh_application_children", lambda node: list(children))
    monkeypatch.setattr(_atspi, "_role_name", lambda node: node.role)
    monkeypatch.setattr(_atspi, "_atspi_wrapper_key", lambda node: node.key)
    assert _atspi.live_window_contexts("wizard") == frozenset({
        ("frame", ":1.5", "/window/1"), ("frame", ":1.5", "/window/2"),
    })
    children.remove(main)  # window destroyed
    assert _atspi.live_window_contexts("wizard") == frozenset({("frame", ":1.5", "/window/2")})
    assert _atspi.live_window_contexts("missing") is None
    assert _atspi.live_window_contexts("") is None
    other.key = None  # native identity unreadable
    assert _atspi.live_window_contexts("wizard") is None
    driver = LinuxDriver()
    monkeypatch.setattr(driver, "_run", lambda fn: fn())
    assert driver.live_window_contexts(None) is None
    def boom(name, scope):
        raise RuntimeError("busy")
    monkeypatch.setattr(_atspi, "find_root", boom)
    assert driver.live_window_contexts("wizard") is None


def _select_all_entry(monkeypatch, *, drop_selection: bool = True):
    """A focused GTK-style entry 'keep me' whose focus grab selects all (#1232)."""
    app = _Acc("application", name="notes")
    entry = _Acc("text", name="Title", states={"SINGLE_LINE", "EDITABLE", "FOCUSED", "ENABLED"})
    entry.get_application = lambda: app
    entry.text = "keep me"
    entry.caret = 7
    entry.selection = None
    entry.get_editable_text_iface = lambda: entry

    def delete_text(start, end):
        entry.text = entry.text[:start] + entry.text[end:]
        entry.caret = start
        entry.selection = None
        return True

    def insert_text(pos, text, length):
        entry.text = entry.text[:pos] + text[:length] + entry.text[pos:]
        entry.caret = pos + length
        return True

    entry.delete_text = delete_text
    entry.insert_text = insert_text

    def grab():
        entry.selection = (0, len(entry.text))
        entry.caret = len(entry.text)
        return True

    monkeypatch.setattr(_atspi, "grab_focus", lambda _acc: grab())
    monkeypatch.setattr(_atspi, "_confirm_focus_on_target", lambda _acc: True)
    monkeypatch.setattr(_atspi, "_x11_keys_available", lambda: True)
    monkeypatch.setattr(_atspi, "peer_field_texts", lambda _acc: {})
    monkeypatch.setattr(observe, "ax_handle_for", lambda *_args: entry)
    driver = LinuxDriver()
    driver._run = lambda fn: fn()
    element = Element("e1", "AXTextField", "Title", "keep me", Bounds(0, 0, 0, 100, 20),
                      "snap-1", editable=True)
    return driver, entry, element


def test_ref_type_into_a_filled_entry_appends_after_focus_selects_all(fake_atspi, monkeypatch):
    """#1232: 'keep me' + ' more' stays 'keep me more' when focus selects all."""
    driver, entry, element = _select_all_entry(monkeypatch)
    assert driver.type_into(element, " more") == 5
    assert entry.text == "keep me more"
    assert entry.selection is None


def test_ref_type_refuses_when_the_select_all_cannot_be_dropped(fake_atspi, monkeypatch):
    """A whole-text selection that stays is refused before any write."""
    driver, entry, element = _select_all_entry(monkeypatch)
    monkeypatch.setattr(_atspi, "collapse_whole_selection_to_end", lambda _acc: False)
    with pytest.raises(ComputerUseError) as exc:
        driver.type_into(element, " more")
    assert exc.value.detail["reason"] == "would_replace_text"
    assert entry.text == "keep me"


def test_ref_type_never_confirms_a_write_that_lost_the_prior_text(fake_atspi, monkeypatch):
    """The read-back compares prior plus typed text, not the typed text alone."""
    driver, entry, element = _select_all_entry(monkeypatch)
    monkeypatch.setattr(driver, "_type_confirmed_handle",
                        lambda handle, text: setattr(handle, "text", text) or len(text))
    with pytest.raises(ComputerUseError) as exc:
        driver.type_into(element, " more")
    assert exc.value.detail["reason"] == "prior_text_lost"
    assert exc.value.detail["expected"] == "keep me more"
    assert exc.value.detail["actual"] == " more"


def test_ref_type_into_an_empty_or_multiline_field_is_untouched(fake_atspi, monkeypatch):
    """Only a single-line entry with text is collapsed; a text view keeps its selection."""
    driver, entry, element = _select_all_entry(monkeypatch)
    entry.states.discard("SINGLE_LINE")
    entry.states.add("MULTI_LINE")
    assert not _atspi.append_target_entry(entry)
    entry.states.discard("MULTI_LINE")
    entry.states.add("SINGLE_LINE")
    entry.text, entry.selection, entry.caret = "", None, 0
    assert _atspi.append_target_entry(entry)


def _calc_comment_tree():
    """Synthetic Calc document with an open comment callout. Not live Calc."""
    app = _Acc("application", name="soffice")
    table = _Acc("table", name="Sheet Data", states={"FOCUSED", "SHOWING"})
    paragraph = _Acc("paragraph", states={"FOCUSED", "EDITABLE", "SHOWING"})
    paragraph.text = ""
    callout = _adopt(_Acc("panel", name="Callout "), paragraph)
    doc = _adopt(_Acc("document spreadsheet"), table, callout)
    for node in (table, paragraph, callout, doc):
        node.get_application = lambda: app
    return doc, table, callout, paragraph


def test_calc_comment_paragraph_is_the_type_read_back(fake_atspi, monkeypatch) -> None:
    """Refs #1249. Synthetic Calc tree. Not a live Calc window.

    FOCUSED stays on the sheet table and is also on the comment callout's
    paragraph. The paragraph is the read-back, so the typed comment is
    confirmed once and not refused as text_mismatch with a retry hint.
    """
    doc, table, callout, paragraph = _calc_comment_tree()
    monkeypatch.setattr(_atspi, "_focused_node", lambda *a, **kw: (table, False))
    assert _atspi.focused_text("soffice") == ""
    paragraph.text = "Added by test"
    assert _atspi.focused_text("soffice") == "Added by test"

    # Not focused, two focused paragraphs, or a table outside a
    # spreadsheet document is not this read-back.
    paragraph.states.discard("FOCUSED")
    assert _atspi._calc_drawing_paragraph(table) is None
    paragraph.states.add("FOCUSED")
    other = _Acc("paragraph", states={"FOCUSED", "SHOWING"})
    _adopt(doc, table, _adopt(_Acc("panel"), other), callout)
    assert _atspi._calc_drawing_paragraph(table) is None
    _adopt(doc, table, callout)
    loose = _adopt(_Acc("document text"), table)
    assert _atspi._calc_drawing_paragraph(table) is None
    _adopt(doc, table, callout)

    paragraph.text = ""
    monkeypatch.setattr(_atspi, "find_root", lambda app, scope: doc)
    monkeypatch.setattr(_atspi, "focused_editable", lambda *a, **kw: None)
    monkeypatch.setattr(_atspi, "sheet_editor_text", lambda app: None)
    monkeypatch.setattr(_atspi, "selected_sheet_text", lambda app: "Cherry")
    monkeypatch.setattr(_atspi, "writer_type_before", lambda app: None)
    monkeypatch.setattr(_atspi, "focused_shape_edit_text", lambda app: None)
    monkeypatch.setattr(_atspi, "spreadsheet_open", lambda app: True)
    monkeypatch.setattr("a11y_computer_use.drivers.linux._on_wayland", lambda: False)
    driver = LinuxDriver()
    monkeypatch.setattr(driver, "_run", lambda fn: fn())
    monkeypatch.setattr(driver, "frontmost_app", lambda: ("soffice", 1))
    sent: list[str] = []

    def type_string(text):
        sent.append(text)
        paragraph.text += text

    monkeypatch.setattr(_linux_input, "type_string", type_string)
    assert driver.type_text("Added by test") == len("Added by test")
    assert sent == ["Added by test"]
    assert paragraph.text == "Added by test"

    # Keys that did not land in the comment are still a mismatch.
    paragraph.text = ""
    monkeypatch.setattr(_atspi, "_TYPE_SETTLE_PAUSE_S", 0)
    monkeypatch.setattr(_atspi.time, "sleep", lambda _s: None)
    monkeypatch.setattr(_linux_input, "type_string", lambda text: None)
    with pytest.raises(ComputerUseError) as exc:
        driver.type_text("Added by test")
    assert exc.value.detail["reason"] == "text_mismatch"
    assert not _atspi.whole_text_selected(entry)
    assert driver.type_into(element, "x") == 1
    assert entry.text == "x"


def test_ref_type_into_a_gtk4_entry_without_a_single_line_state_appends(fake_atspi, monkeypatch):
    """#1232: GTK 4 marks an entry neither SINGLE_LINE nor MULTI_LINE."""
    driver, entry, element = _select_all_entry(monkeypatch)
    entry.states.discard("SINGLE_LINE")
    assert _atspi.append_target_entry(entry)
    assert driver.type_into(element, " more") == 5
    assert entry.text == "keep me more"
    assert entry.selection is None


def test_ref_type_keeps_the_selection_of_a_stateless_text_with_line_breaks(fake_atspi, monkeypatch):
    """A text role with line breaks and no single-line state is an editor, not an entry."""
    _driver, entry, _element = _select_all_entry(monkeypatch)
    entry.states.discard("SINGLE_LINE")
    entry.text = "one\ntwo"
    assert not _atspi.append_target_entry(entry)


def test_chromium_snapshot_root_clears_again_when_the_cleared_read_is_empty() -> None:
    """Synthetic AT-SPI nodes, not a live Chrome.

    The one clear per latch can run while Escape is still closing the find
    bar. libatspi then caches only the empty untitled frame. A later read of
    that pid must clear again and return the titled page window, not the
    empty group (the scroll_to_find ROW-0300 "not found after 0 scroll(s)",
    "last_rows: none" CI flake). A cleared read that is already the page is
    not cleared again.
    """

    class _States:
        def __init__(self, names):
            self.names = frozenset(names)

    clears: list[str] = []

    class _Node:
        def __init__(self, name, *, role="frame", children=(), states=(), pid=6262):
            self._name = name
            self._role = role
            self._children = list(children)
            self._fresh = None
            self._states = frozenset(states)
            self._pid = pid
            self._app = None

        def get_name(self):
            return self._name

        def get_role_name(self):
            return self._role

        def get_child_count(self):
            return len(self._children)

        def get_child_at_index(self, index):
            return self._children[index]

        def get_state_set(self):
            return _States(self._states)

        def get_process_id(self):
            return self._pid

        def get_application(self):
            return self._app

        def get_toolkit_name(self):
            return "Chrome"

        def clear_cache(self):
            clears.append(self._role)
            if self._fresh is not None:
                self._children = list(self._fresh)

    filler = _Node("", role="panel")
    empty = _Node("", children=[_Node("", role="panel", children=[filler])],
                  states=("ACTIVE", "SHOWING"))
    page = _Node("rowtable - Google Chrome", states=("SHOWING",),
                 children=[_Node("rowtable", role="document web")])
    app = _Node("Google Chrome", role="application", children=[empty])
    app._fresh = [empty, page]
    empty._app = app
    page._app = app

    _atspi._BROWSER_BAR_PIDS.clear()
    _atspi._BROWSER_BAR_CLEARED.clear()
    _atspi._BROWSER_BAR_OPEN.clear()
    try:
        _atspi._BROWSER_BAR_PIDS.add(6262)
        _atspi._BROWSER_BAR_CLEARED.add(6262)
        assert _atspi.chromium_snapshot_root(empty) is page
        assert "application" in clears
        clears.clear()
        assert _atspi.chromium_snapshot_root(empty) is page
        assert clears == []
    finally:
        _atspi._BROWSER_BAR_PIDS.clear()
        _atspi._BROWSER_BAR_CLEARED.clear()
        _atspi._BROWSER_BAR_OPEN.clear()


def _lo_validity_popup(window_role: str = "window"):
    """Synthetic LibreOffice validity list. Not a live Calc window.

    A GTK tree table of entries inside an undecorated popup ``window``.
    select_child marks the row SELECTED, as GTK does, without committing.
    """
    red = _outline_cell("Red", ["expand or contract", "edit", "activate"])
    green = _outline_cell("Green", ["expand or contract", "edit", "activate"])
    window = _outline_window(red, green)
    window.role = window_role
    app = green.get_application()
    app.name = "soffice"
    return window, red, green


def test_libreoffice_validity_row_is_a_popup_row_without_double_click_note(fake_atspi) -> None:
    """Refs #1247. Synthetic tree. Not a live Calc window."""
    _window, red, green = _lo_validity_popup()
    assert _atspi.libreoffice_popup_list_row(green) is True
    assert _atspi.libreoffice_popup_list_row(red) is True
    assert _atspi.outline_double_click_note(green) == ""
    framed, _red, framed_green = _lo_validity_popup(window_role="frame")
    assert _atspi.libreoffice_popup_list_row(framed_green) is False
    assert _atspi.outline_double_click_note(framed_green) == "activates on double-click"
    _plain, _r, other = _lo_validity_popup()
    other.get_application().name = "treeprobe"
    assert _atspi.libreoffice_popup_list_row(other) is False


def test_libreoffice_validity_row_click_is_a_pointer_click_not_select_child(fake_atspi, monkeypatch) -> None:
    """Refs #1247. Synthetic tree. Not a live Calc window.

    select_child only highlights the row and Return then commits the old
    entry. The ref click sends one pointer click and succeeds only when the
    popup closes. A popup that stays open is an error, not success.
    """
    _window, _red, green = _lo_validity_popup()
    tree = green.get_parent()
    selected: list[int] = []
    tree.select_child = lambda index: selected.append(index) or True
    clicks: list[object] = []

    def click(self, target, **_kwargs):
        clicks.append(target)
        green.states.discard("SHOWING")

    monkeypatch.setattr(LinuxDriver, "click", click)
    monkeypatch.setattr(observe, "ax_handle_for", lambda *_args: green)
    monkeypatch.setattr(_atspi.time, "sleep", lambda _seconds: None)
    monkeypatch.delenv("A11Y_COMPUTER_USE_ATSPI_EVENTS", raising=False)
    element = Element("e4", "AXCell", "Green", None, Bounds(0, 48, 121, 180, 21), "snap-1", clickable=True)
    assert LinuxDriver().press_element(element) is True
    assert clicks == [element]
    assert selected == []

    _window, _red, stuck = _lo_validity_popup()
    clicks.clear()
    monkeypatch.setattr(LinuxDriver, "click", lambda self, target, **_kw: clicks.append(target))
    monkeypatch.setattr(observe, "ax_handle_for", lambda *_args: stuck)
    ticks = iter(range(0, 1000))
    monkeypatch.setattr(_atspi.time, "monotonic", lambda: float(next(ticks)))
    with pytest.raises(ComputerUseError) as exc:
        LinuxDriver().press_element(element)
    assert exc.value.detail["reason"] == "popup_not_closed"
    assert clicks == [element]
